window.CODIGO = {"lab1":[{"nombre":"Main.java","ruta":"prog5-base/src/main/java/com/unachi/prog5/Main.java","lenguaje":"java","lineas":11,"texto":"package com.unachi.prog5;\n\nimport com.unachi.prog5.controller.AppController;\nimport com.unachi.prog5.view.ConsoleView;\n\npublic class Main {\n    public static void main(String[] args) {\n        AppController controller = new AppController(new ConsoleView());\n        controller.run();\n    }\n}"},{"nombre":"Student.java","ruta":"prog5-base/src/main/java/com/unachi/prog5/model/Student.java","lenguaje":"java","lineas":15,"texto":"package com.unachi.prog5.model;\n\npublic class Student {\n    private final String id;\n    private final String name;\n\n    public Student(String id, String name) {\n        this.id = id;\n        this.name = name;\n    }\n\n    public String summary() {\n        return \"Student{id='\" + id + \"', name='\" + name + \"'}\";\n    }\n}"},{"nombre":"ConsoleView.java","ruta":"prog5-base/src/main/java/com/unachi/prog5/view/ConsoleView.java","lenguaje":"java","lineas":7,"texto":"package com.unachi.prog5.view;\n\npublic class ConsoleView {\n    public void showMessage(String msg) {\n        System.out.println(msg);\n    }\n}"},{"nombre":"AppController.java","ruta":"prog5-base/src/main/java/com/unachi/prog5/controller/AppController.java","lenguaje":"java","lineas":18,"texto":"package com.unachi.prog5.controller;\n\nimport com.unachi.prog5.model.Student;\nimport com.unachi.prog5.view.ConsoleView;\n\npublic class AppController {\n    private final ConsoleView view;\n\n    public AppController(ConsoleView view) {\n        this.view = view;\n    }\n\n    public void run() {\n        Student s = new Student(\"2026-001\", \"Nombre Apellido\");\n        view.showMessage(\"Hola Programacion V\");\n        view.showMessage(\"Modelo: \" + s.summary());\n    }\n}"},{"nombre":"pom.xml","ruta":"prog5-base/pom.xml","lenguaje":"xml","lineas":29,"texto":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<project xmlns=\"http://maven.apache.org/POM/4.0.0\"\n         xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"\n         xsi:schemaLocation=\"http://maven.apache.org/POM/4.0.0 http://maven.apache.org/xsd/maven-4.0.0.xsd\">\n    <modelVersion>4.0.0</modelVersion>\n\n    <groupId>com.unachi.prog5</groupId>\n    <artifactId>prog5-base</artifactId>\n    <version>1.0.0</version>\n    <packaging>jar</packaging>\n\n    <properties>\n        <maven.compiler.release>17</maven.compiler.release>\n        <project.build.sourceEncoding>UTF-8</project.build.sourceEncoding>\n    </properties>\n\n    <build>\n        <plugins>\n            <plugin>\n                <groupId>org.codehaus.mojo</groupId>\n                <artifactId>exec-maven-plugin</artifactId>\n                <version>3.5.0</version>\n                <configuration>\n                    <mainClass>com.unachi.prog5.Main</mainClass>\n                </configuration>\n            </plugin>\n        </plugins>\n    </build>\n</project>"}],"lab2":[{"nombre":"MaestroEsclavoFacturas.java","ruta":"patrones/src/main/java/MaestroEsclavoFacturas.java","lenguaje":"java","lineas":154,"texto":"import java.util.ArrayList;\nimport java.util.List;\nimport java.util.concurrent.*;\n\n/**\n * Ejemplo del patrón MAESTRO-ESCLAVO (Master-Slave)\n * Caso de uso: Procesamiento distribuido de un lote de facturas.\n *\n * El MAESTRO (clase CoordinadorFacturacion) divide el lote de facturas en\n * sublotes independientes y se los asigna a varios ESCLAVOS (tareas\n * NodoDeCalculo), que se ejecutan en paralelo usando un ExecutorService.\n * Cada esclavo calcula el ITBMS y el total de su sublote sin necesitar\n * información de los demás. El maestro combina los resultados parciales\n * en un único reporte consolidado.\n *\n * Compilar:  javac MaestroEsclavoFacturas.java\n * Ejecutar:  java MaestroEsclavoFacturas\n */\npublic class MaestroEsclavoFacturas {\n\n    // --------------------------------------------------------------\n    // Modelo de datos: una factura simple con su monto sin impuestos.\n    // --------------------------------------------------------------\n    record Factura(int id, double montoSinImpuesto) { }\n\n    // --------------------------------------------------------------\n    // Resultado parcial que devuelve cada ESCLAVO al maestro.\n    // --------------------------------------------------------------\n    record ResultadoParcial(int idNodo, int facturasProcesadas,\n                             double totalSinImpuesto, double totalItbms,\n                             double totalConImpuesto) { }\n\n    // --------------------------------------------------------------\n    // ESCLAVO: procesa un sublote de facturas de forma independiente.\n    // Implementa Callable<ResultadoParcial> para poder ejecutarse en\n    // un hilo del pool y devolver un resultado a través de un Future.\n    // --------------------------------------------------------------\n    static class NodoDeCalculo implements Callable<ResultadoParcial> {\n        private static final double TASA_ITBMS = 0.07;\n\n        private final int idNodo;\n        private final List<Factura> sublote;\n\n        NodoDeCalculo(int idNodo, List<Factura> sublote) {\n            this.idNodo = idNodo;\n            this.sublote = sublote;\n        }\n\n        @Override\n        public ResultadoParcial call() {\n            double totalSinImpuesto = 0.0;\n            for (Factura f : sublote) {\n                totalSinImpuesto += f.montoSinImpuesto();\n            }\n            double totalItbms = totalSinImpuesto * TASA_ITBMS;\n            double totalConImpuesto = totalSinImpuesto + totalItbms;\n\n            System.out.printf(\"  [Esclavo %d] procesó %d facturas -> subtotal: %.2f, ITBMS: %.2f%n\",\n                    idNodo, sublote.size(), totalSinImpuesto, totalItbms);\n\n            return new ResultadoParcial(idNodo, sublote.size(),\n                    totalSinImpuesto, totalItbms, totalConImpuesto);\n        }\n    }\n\n    // --------------------------------------------------------------\n    // MAESTRO: divide el trabajo, distribuye a los esclavos y\n    // consolida los resultados parciales en un reporte final.\n    // --------------------------------------------------------------\n    static class CoordinadorFacturacion {\n\n        ResultadoParcial procesarLote(List<Factura> lote, int cantidadEsclavos) {\n\n            // 1) Dividir el lote en sublotes lo más parejos posible.\n            List<List<Factura>> sublotes = dividirEnSublotes(lote, cantidadEsclavos);\n\n            // 2) Crear un pool de hilos: uno por esclavo.\n            ExecutorService pool = Executors.newFixedThreadPool(cantidadEsclavos);\n            List<Future<ResultadoParcial>> futuros = new ArrayList<>();\n\n            System.out.println(\"[Maestro] Repartiendo \" + lote.size() + \" facturas en \"\n                    + sublotes.size() + \" sublotes...\");\n\n            // 3) Distribuir subtareas: cada sublote se manda a un esclavo distinto.\n            for (int i = 0; i < sublotes.size(); i++) {\n                NodoDeCalculo esclavo = new NodoDeCalculo(i + 1, sublotes.get(i));\n                futuros.add(pool.submit(esclavo));\n            }\n\n            // 4) Recoger los resultados parciales (esperando a cada esclavo).\n            double totalSinImpuesto = 0.0;\n            double totalItbms = 0.0;\n            double totalConImpuesto = 0.0;\n            int facturasProcesadas = 0;\n\n            try {\n                for (Future<ResultadoParcial> futuro : futuros) {\n                    ResultadoParcial parcial = futuro.get(); // bloquea hasta tener el resultado\n                    totalSinImpuesto += parcial.totalSinImpuesto();\n                    totalItbms += parcial.totalItbms();\n                    totalConImpuesto += parcial.totalConImpuesto();\n                    facturasProcesadas += parcial.facturasProcesadas();\n                }\n            } catch (InterruptedException | ExecutionException e) {\n                throw new RuntimeException(\"Error al recolectar resultados de un esclavo\", e);\n            } finally {\n                pool.shutdown();\n            }\n\n            // 5) Consolidar en el reporte final.\n            return new ResultadoParcial(0, facturasProcesadas,\n                    totalSinImpuesto, totalItbms, totalConImpuesto);\n        }\n\n        private List<List<Factura>> dividirEnSublotes(List<Factura> lote, int cantidadEsclavos) {\n            List<List<Factura>> sublotes = new ArrayList<>();\n            int tamanoBase = lote.size() / cantidadEsclavos;\n            int resto = lote.size() % cantidadEsclavos;\n            int inicio = 0;\n\n            for (int i = 0; i < cantidadEsclavos; i++) {\n                int tamanoSublote = tamanoBase + (i < resto ? 1 : 0);\n                if (tamanoSublote == 0) continue;\n                int fin = inicio + tamanoSublote;\n                sublotes.add(lote.subList(inicio, fin));\n                inicio = fin;\n            }\n            return sublotes;\n        }\n    }\n\n    // --------------------------------------------------------------\n    // Programa de demostración.\n    // --------------------------------------------------------------\n    public static void main(String[] args) {\n        // Generamos un lote de ejemplo (20 facturas simuladas).\n        List<Factura> lote = new ArrayList<>();\n        for (int i = 1; i <= 20; i++) {\n            double monto = 50 + (i * 7.35); // montos variados de ejemplo\n            lote.add(new Factura(i, monto));\n        }\n\n        CoordinadorFacturacion maestro = new CoordinadorFacturacion();\n        ResultadoParcial reporte = maestro.procesarLote(lote, 4); // 4 esclavos\n\n        System.out.println();\n        System.out.println(\"===== REPORTE CONSOLIDADO DE FACTURACIÓN =====\");\n        System.out.printf(\"Facturas procesadas : %d%n\", reporte.facturasProcesadas());\n        System.out.printf(\"Subtotal            : %.2f%n\", reporte.totalSinImpuesto());\n        System.out.printf(\"Total ITBMS (7%%)    : %.2f%n\", reporte.totalItbms());\n        System.out.printf(\"TOTAL CON IMPUESTO   : %.2f%n\", reporte.totalConImpuesto());\n    }\n}\n"},{"nombre":"PipeFilterLogs.java","ruta":"patrones/src/main/java/PipeFilterLogs.java","lenguaje":"java","lineas":146,"texto":"import java.util.ArrayList;\nimport java.util.LinkedHashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.function.Function;\n\n/**\n * Ejemplo del patrón FILTRO DE TUBERÍA (Pipe-Filter)\n * Caso de uso: Análisis de logs del sistema.\n *\n * Los datos fluyen a través de una secuencia de FILTROS independientes:\n *   Entrada (logs crudos)\n *     -> Filtro 1: filtrado de errores (nivel ERROR/WARN)\n *     -> Filtro 2: agregación por tipo de error\n *     -> Filtro 3: generación de reporte\n *   -> Salida (reporte de incidencias)\n *\n * Cada filtro se modela como una interfaz funcional Filtro<E, S> que\n * transforma una entrada de tipo E en una salida de tipo S, sin conocer\n * nada de los demás filtros. La clase Tuberia los conecta en secuencia.\n *\n * Compilar:  javac PipeFilterLogs.java\n * Ejecutar:  java PipeFilterLogs\n */\npublic class PipeFilterLogs {\n\n    // --------------------------------------------------------------\n    // Interfaz genérica de un FILTRO: recibe una entrada E y produce\n    // una salida S. Extiende Function para poder encadenarse con\n    // .andThen(...) si se desea, aunque aquí los conectamos explícitamente\n    // en la clase Tuberia para que el flujo quede más visible.\n    // --------------------------------------------------------------\n    interface Filtro<E, S> extends Function<E, S> { }\n\n    // --------------------------------------------------------------\n    // Modelo de datos: una línea de log ya parseada.\n    // --------------------------------------------------------------\n    record LineaLog(String nivel, String tipoError, String mensaje) { }\n\n    record Incidencia(String tipoError, int ocurrencias) { }\n\n    // --------------------------------------------------------------\n    // FILTRO 1: Filtrado de errores.\n    // Entrada:  lista de líneas de log crudas.\n    // Salida:   solo las líneas de nivel ERROR o WARN.\n    // --------------------------------------------------------------\n    static class FiltroDeErrores implements Filtro<List<LineaLog>, List<LineaLog>> {\n        @Override\n        public List<LineaLog> apply(List<LineaLog> logsCrudos) {\n            List<LineaLog> filtradas = new ArrayList<>();\n            for (LineaLog linea : logsCrudos) {\n                if (linea.nivel().equals(\"ERROR\") || linea.nivel().equals(\"WARN\")) {\n                    filtradas.add(linea);\n                }\n            }\n            System.out.println(\"[Filtro 1 - Filtrado de errores] \" + logsCrudos.size()\n                    + \" líneas -> \" + filtradas.size() + \" relevantes (ERROR/WARN)\");\n            return filtradas;\n        }\n    }\n\n    // --------------------------------------------------------------\n    // FILTRO 2: Agregación por tipo de error.\n    // Entrada:  líneas ya filtradas (solo ERROR/WARN).\n    // Salida:   conteo de ocurrencias agrupado por tipo de error.\n    // --------------------------------------------------------------\n    static class FiltroDeAgregacion implements Filtro<List<LineaLog>, List<Incidencia>> {\n        @Override\n        public List<Incidencia> apply(List<LineaLog> lineasFiltradas) {\n            Map<String, Integer> conteos = new LinkedHashMap<>();\n            for (LineaLog linea : lineasFiltradas) {\n                conteos.merge(linea.tipoError(), 1, Integer::sum);\n            }\n\n            List<Incidencia> incidencias = new ArrayList<>();\n            for (Map.Entry<String, Integer> entrada : conteos.entrySet()) {\n                incidencias.add(new Incidencia(entrada.getKey(), entrada.getValue()));\n            }\n\n            System.out.println(\"[Filtro 2 - Agregación por tipo] \" + incidencias.size()\n                    + \" tipos de error distintos encontrados\");\n            return incidencias;\n        }\n    }\n\n    // --------------------------------------------------------------\n    // FILTRO 3: Generación de reporte.\n    // Entrada:  incidencias agregadas.\n    // Salida:   texto del reporte final, listo para el equipo de soporte.\n    // --------------------------------------------------------------\n    static class FiltroDeReporte implements Filtro<List<Incidencia>, String> {\n        @Override\n        public String apply(List<Incidencia> incidencias) {\n            StringBuilder reporte = new StringBuilder();\n            reporte.append(\"===== REPORTE DE INCIDENCIAS =====\\n\");\n            for (Incidencia inc : incidencias) {\n                reporte.append(String.format(\"- %-20s : %d ocurrencia(s)%n\",\n                        inc.tipoError(), inc.ocurrencias()));\n            }\n            System.out.println(\"[Filtro 3 - Generación de reporte] reporte final construido\");\n            return reporte.toString();\n        }\n    }\n\n    // --------------------------------------------------------------\n    // TUBERÍA: conecta los filtros en secuencia. No conoce el contenido\n    // de cada filtro, solo los ejecuta uno tras otro pasando la salida\n    // de uno como entrada del siguiente.\n    // --------------------------------------------------------------\n    static class Tuberia {\n        private final FiltroDeErrores filtro1 = new FiltroDeErrores();\n        private final FiltroDeAgregacion filtro2 = new FiltroDeAgregacion();\n        private final FiltroDeReporte filtro3 = new FiltroDeReporte();\n\n        String procesar(List<LineaLog> logsCrudos) {\n            List<LineaLog> filtradas = filtro1.apply(logsCrudos);\n            List<Incidencia> incidencias = filtro2.apply(filtradas);\n            return filtro3.apply(incidencias);\n        }\n    }\n\n    // --------------------------------------------------------------\n    // Programa de demostración.\n    // --------------------------------------------------------------\n    public static void main(String[] args) {\n        // Simulamos logs crudos del servidor (entrada de la tubería).\n        List<LineaLog> logsCrudos = List.of(\n                new LineaLog(\"INFO\", \"-\", \"Servidor iniciado correctamente\"),\n                new LineaLog(\"ERROR\", \"ConexionBD\", \"No se pudo conectar a la base de datos\"),\n                new LineaLog(\"DEBUG\", \"-\", \"Cache actualizada\"),\n                new LineaLog(\"WARN\", \"Timeout\", \"La respuesta tardó más de 5s\"),\n                new LineaLog(\"ERROR\", \"Autenticacion\", \"Token expirado\"),\n                new LineaLog(\"ERROR\", \"ConexionBD\", \"Timeout al conectar a la base de datos\"),\n                new LineaLog(\"INFO\", \"-\", \"Usuario admin inició sesión\"),\n                new LineaLog(\"WARN\", \"Timeout\", \"La respuesta tardó más de 5s\"),\n                new LineaLog(\"ERROR\", \"Autenticacion\", \"Credenciales inválidas\")\n        );\n\n        Tuberia tuberia = new Tuberia();\n        String reporteFinal = tuberia.procesar(logsCrudos);\n\n        System.out.println();\n        System.out.println(reporteFinal);\n    }\n}\n"},{"nombre":"CuentaBancaria.java","ruta":"poo-cuenta-bancaria/src/objetos/CuentaBancaria.java","lenguaje":"java","lineas":60,"texto":"package objetos;\n\npublic class CuentaBancaria {\n    private String numerocuenta;\n    private String nombrecuenta;\n    private double saldo;\n    private int tipocuenta;\n    private int estado; // 1 activa 0 inactiva\n\n    public int getEstado() {\n        return estado;\n    }\n\n    public void setEstado(int estado) {\n        if ((estado == 0) || (estado == 1))\n            this.estado = estado;\n    }\n\n    public String getNumerocuenta() {\n        return numerocuenta;\n    }\n\n    public void setNumerocuenta(String numerocuenta) {\n        this.numerocuenta = numerocuenta;\n    }\n\n    public String getNombrecuenta() {\n        return nombrecuenta;\n    }\n\n    public void setNombrecuenta(String nombrecuenta) {\n        this.nombrecuenta = nombrecuenta;\n    }\n\n    public double getSaldo() {\n        return saldo;\n    }\n\n    public void setSaldo(double saldo) {\n        if (saldo > 0) {\n            this.saldo = saldo;\n        }\n    }\n\n    public int getTipocuenta() {\n        return tipocuenta;\n    }\n\n    public void setTipocuenta(int tipocuenta) {\n        this.tipocuenta = tipocuenta;\n    }\n\n    public int depositar(double monto) {\n        if (monto > 0) {\n            this.saldo += monto;\n            return 1;\n        } else\n            return 0;\n    }\n}"},{"nombre":"Persona.java","ruta":"poo-cuenta-bancaria/src/objetos/Persona.java","lenguaje":"java","lineas":6,"texto":"package objetos;\n\npublic class Persona {\n    public String nombre;\n    public int edad;\n}"},{"nombre":"Main.java","ruta":"poo-cuenta-bancaria/src/objetos/Main.java","lenguaje":"java","lineas":32,"texto":"package objetos;\n\npublic class Main {\n\n    public static void main(String[] args) {\n        Persona p1 = new Persona();\n        CuentaBancaria juan = new CuentaBancaria();\n        CuentaBancaria enrique = new CuentaBancaria();\n\n        p1.nombre = \"\";\n        p1.edad = 0;\n\n        juan.setNumerocuenta(\"1-2000-988\");\n        juan.setSaldo(10.0);\n        System.out.println(juan.getSaldo());\n        juan.setSaldo(-25.0);\n        System.out.println(juan.getSaldo());\n        juan.setEstado(1);\n        System.out.println(\"El estado es \" + juan.getEstado());\n\n        enrique.setSaldo(100.00);\n        enrique.setNombrecuenta(\"Enrique\");\n        System.out.println(enrique.getNombrecuenta() + enrique.getSaldo());\n        enrique.setSaldo(1);\n        int i = enrique.depositar(0.9);\n        if (i == 1)\n            System.out.println(\"Operacion de Deposito Exitosa\");\n        else {\n            System.out.println(\"Operacion de Deposito No Exitosa\");\n        }\n    }\n}"},{"nombre":"Empleado.java","ruta":"taller-poo/codigo_completo/Empleado.java","lenguaje":"java","lineas":64,"texto":"/**\n * Clase ABSTRACTA Empleado.\n * ---------------------------------------------------------------------\n * Es la clase base de toda la jerarquía de empleados de la empresa.\n * Es \"abstracta\" porque no tiene sentido crear un objeto genérico\n * \"Empleado\" sin saber qué tipo específico es (Gerente, Vendedor,\n * Operario) — cada tipo calcula su salario de forma distinta.\n *\n * NO debes modificar este archivo. Solo debes leerlo y entender cómo\n * funciona, porque Gerente, Vendedor y Operario heredan de él.\n * ---------------------------------------------------------------------\n */\npublic abstract class Empleado {\n\n    // Atributos: el estado que TODO empleado tiene, sin importar su tipo.\n    protected String nombre;\n    protected String cedula;\n    protected double salarioBase;\n\n    // Constructor: inicializa los atributos comunes a todos los empleados.\n    public Empleado(String nombre, String cedula, double salarioBase) {\n        this.nombre = nombre;\n        this.cedula = cedula;\n        this.salarioBase = salarioBase;\n    }\n\n    // Getters (encapsulamiento): forma controlada de leer los atributos.\n    public String getNombre() {\n        return nombre;\n    }\n\n    public String getCedula() {\n        return cedula;\n    }\n\n    public double getSalarioBase() {\n        return salarioBase;\n    }\n\n    /**\n     * Método ABSTRACTO: no tiene cuerpo aquí. Cada subclase (Gerente,\n     * Vendedor, Operario) ESTÁ OBLIGADA a implementarlo a su manera.\n     * Esto es la base del polimorfismo: el mismo nombre de método,\n     * comportamientos distintos según el objeto real que lo ejecute.\n     */\n    public abstract double calcularSalario();\n\n    /**\n     * Método normal (no abstracto): todas las subclases lo heredan\n     * igual, pero como usa calcularSalario() por dentro, el resultado\n     * cambia automáticamente según el tipo real del objeto.\n     */\n    public String mostrarInfo() {\n        return String.format(\"%-10s | %-12s | %-10s | $%.2f\",\n                tipoDeEmpleado(), nombre, cedula, calcularSalario());\n    }\n\n    /**\n     * Método abstracto adicional: cada subclase dice qué tipo de\n     * empleado es (útil para mostrarlo en el reporte).\n     */\n    public abstract String tipoDeEmpleado();\n}\n"},{"nombre":"Gerente.java","ruta":"taller-poo/codigo_completo/Gerente.java","lenguaje":"java","lineas":34,"texto":"/**\n * Clase Gerente — EJEMPLO COMPLETO Y RESUELTO.\n * ---------------------------------------------------------------------\n * Úsala como modelo para completar Vendedor.java y Operario.java.\n * No necesitas modificar este archivo.\n *\n * Un Gerente gana su salario base MÁS un bono fijo por dirección de\n * equipo.\n * ---------------------------------------------------------------------\n */\npublic class Gerente extends Empleado {\n\n    // Atributo PROPIO de Gerente (no existe en la clase base Empleado).\n    private double bonoDireccion;\n\n    // Constructor: primero inicializa lo que es común (con super(...)),\n    // luego lo que es propio de esta subclase.\n    public Gerente(String nombre, String cedula, double salarioBase, double bonoDireccion) {\n        super(nombre, cedula, salarioBase);\n        this.bonoDireccion = bonoDireccion;\n    }\n\n    // Implementación PROPIA de calcularSalario() para un Gerente.\n    @Override\n    public double calcularSalario() {\n        return salarioBase + bonoDireccion;\n    }\n\n    @Override\n    public String tipoDeEmpleado() {\n        return \"Gerente\";\n    }\n}\n"},{"nombre":"Operario.java","ruta":"taller-poo/codigo_completo/Operario.java","lenguaje":"java","lineas":32,"texto":"/**\n * Clase Operario — VERSIÓN RESUELTA (clave de corrección para el docente).\n * ---------------------------------------------------------------------\n * Un Operario gana su salario base MÁS un pago extra por cada hora\n * adicional trabajada (horas extra).\n *\n * Fórmula: salario final = salarioBase + (horasExtra * pagoPorHoraExtra)\n * ---------------------------------------------------------------------\n */\npublic class Operario extends Empleado {\n\n    private int horasExtra;\n    private double pagoPorHoraExtra;\n\n    public Operario(String nombre, String cedula, double salarioBase,\n                     int horasExtra, double pagoPorHoraExtra) {\n        super(nombre, cedula, salarioBase);\n        this.horasExtra = horasExtra;\n        this.pagoPorHoraExtra = pagoPorHoraExtra;\n    }\n\n    @Override\n    public double calcularSalario() {\n        return salarioBase + (horasExtra * pagoPorHoraExtra);\n    }\n\n    @Override\n    public String tipoDeEmpleado() {\n        return \"Operario\";\n    }\n}\n"},{"nombre":"Vendedor.java","ruta":"taller-poo/codigo_completo/Vendedor.java","lenguaje":"java","lineas":32,"texto":"/**\n * Clase Vendedor — VERSIÓN RESUELTA (clave de corrección para el docente).\n * ---------------------------------------------------------------------\n * Un Vendedor gana su salario base MÁS una comisión, que es un\n * porcentaje del monto total de ventas que realizó en el mes.\n *\n * Fórmula: salario final = salarioBase + (montoVentas * porcentajeComision)\n * ---------------------------------------------------------------------\n */\npublic class Vendedor extends Empleado {\n\n    private double montoVentas;\n    private double porcentajeComision;\n\n    public Vendedor(String nombre, String cedula, double salarioBase,\n                     double montoVentas, double porcentajeComision) {\n        super(nombre, cedula, salarioBase);\n        this.montoVentas = montoVentas;\n        this.porcentajeComision = porcentajeComision;\n    }\n\n    @Override\n    public double calcularSalario() {\n        return salarioBase + (montoVentas * porcentajeComision);\n    }\n\n    @Override\n    public String tipoDeEmpleado() {\n        return \"Vendedor\";\n    }\n}\n"},{"nombre":"Main.java","ruta":"taller-poo/codigo_completo/Main.java","lenguaje":"java","lineas":62,"texto":"import java.util.ArrayList;\nimport java.util.List;\n\n/**\n * Clase Main — YA ESTÁ COMPLETA, no la modifiques todavía.\n * ---------------------------------------------------------------------\n * Aquí está la magia del POLIMORFISMO: creamos una sola lista de tipo\n * Empleado (la clase base), pero dentro guardamos objetos de tres tipos\n * DISTINTOS (Gerente, Vendedor, Operario).\n *\n * Cuando recorremos la lista y llamamos empleado.mostrarInfo(), Java\n * decide EN TIEMPO DE EJECUCIÓN cuál versión de calcularSalario() usar,\n * según el tipo REAL del objeto — no según el tipo de la variable.\n * Eso es polimorfismo: \"una interfaz, muchas formas\".\n * ---------------------------------------------------------------------\n */\npublic class Main {\n    public static void main(String[] args) {\n\n        // Una sola lista de tipo Empleado (la clase base / abstracta)...\n        List<Empleado> nomina = new ArrayList<>();\n\n        // ...pero llena de objetos de subclases distintas.\n        nomina.add(new Gerente(\"Ana Pérez\", \"8-123-456\", 1200.00, 400.00));\n        nomina.add(new Vendedor(\"Luis Gómez\", \"4-789-012\", 800.00, 5000.00, 0.05));\n        nomina.add(new Vendedor(\"Carla Ruiz\", \"1-456-789\", 800.00, 12000.00, 0.05));\n        nomina.add(new Operario(\"José Ríos\", \"9-321-654\", 700.00, 10, 4.50));\n\n        System.out.println(\"===== REPORTE DE NÓMINA =====\");\n        System.out.printf(\"%-10s | %-12s | %-10s | %s%n\", \"Tipo\", \"Nombre\", \"Cédula\", \"Salario final\");\n        System.out.println(\"---------------------------------------------------------------\");\n\n        double totalNomina = 0;\n\n        // Mismo método llamado sobre CADA objeto, comportamiento distinto\n        // según el tipo real (¡esto es polimorfismo en acción!).\n        for (Empleado empleado : nomina) {\n            System.out.println(empleado.mostrarInfo());\n            totalNomina += empleado.calcularSalario();\n        }\n\n        System.out.println(\"---------------------------------------------------------------\");\n        System.out.printf(\"TOTAL A PAGAR ESTE MES: $%.2f%n\", totalNomina);\n\n        // ------------------------------------------------------------\n        // Extra: instanceof — a veces necesitamos saber el tipo real\n        // de un objeto para hacer algo específico de esa subclase.\n        // ------------------------------------------------------------\n        System.out.println();\n        System.out.println(\"===== VENDEDORES CON COMISIÓN DESTACADA (> $500) =====\");\n        for (Empleado empleado : nomina) {\n            if (empleado instanceof Vendedor) {\n                Vendedor v = (Vendedor) empleado; // downcasting\n                double comision = v.calcularSalario() - v.getSalarioBase();\n                if (comision > 500) {\n                    System.out.printf(\"%s generó una comisión de $%.2f%n\", v.getNombre(), comision);\n                }\n            }\n        }\n    }\n}\n"}],"lab4":[{"nombre":"MvcEstudiantesApplication.java","ruta":"mvc-estudiantes/src/main/java/pa/ac/unachi/mvcestudiantes/MvcEstudiantesApplication.java","lenguaje":"java","lineas":13,"texto":"package pa.ac.unachi.mvcestudiantes;\n\nimport org.springframework.boot.SpringApplication;\nimport org.springframework.boot.autoconfigure.SpringBootApplication;\n\n@SpringBootApplication\npublic class MvcEstudiantesApplication {\n\n    public static void main(String[] args) {\n        SpringApplication.run(MvcEstudiantesApplication.class, args);\n    }\n}\n"},{"nombre":"Estudiante.java","ruta":"mvc-estudiantes/src/main/java/pa/ac/unachi/mvcestudiantes/model/Estudiante.java","lenguaje":"java","lineas":62,"texto":"package pa.ac.unachi.mvcestudiantes.model;\n\nimport jakarta.persistence.*;\nimport jakarta.validation.constraints.Email;\nimport jakarta.validation.constraints.NotBlank;\nimport jakarta.validation.constraints.Size;\n\n@Entity\n@Table(name = \"estudiantes\")\npublic class Estudiante {\n\n    @Id\n    @GeneratedValue(strategy = GenerationType.IDENTITY)\n    private Long id;\n\n    @NotBlank(message = \"La cédula es obligatoria\")\n    @Size(max = 20)\n    @Column(nullable = false, unique = true, length = 20)\n    private String cedula;\n\n    @NotBlank(message = \"El nombre es obligatorio\")\n    @Size(max = 80)\n    @Column(nullable = false, length = 80)\n    private String nombre;\n\n    @NotBlank(message = \"El apellido es obligatorio\")\n    @Size(max = 80)\n    @Column(nullable = false, length = 80)\n    private String apellido;\n\n    @NotBlank(message = \"El correo es obligatorio\")\n    @Email(message = \"Ingrese un correo válido\")\n    @Size(max = 120)\n    @Column(nullable = false, length = 120)\n    private String correo;\n\n    @NotBlank(message = \"La carrera es obligatoria\")\n    @Size(max = 120)\n    @Column(nullable = false, length = 120)\n    private String carrera;\n\n    public Estudiante() {}\n\n    public Long getId() { return id; }\n    public void setId(Long id) { this.id = id; }\n\n    public String getCedula() { return cedula; }\n    public void setCedula(String cedula) { this.cedula = cedula; }\n\n    public String getNombre() { return nombre; }\n    public void setNombre(String nombre) { this.nombre = nombre; }\n\n    public String getApellido() { return apellido; }\n    public void setApellido(String apellido) { this.apellido = apellido; }\n\n    public String getCorreo() { return correo; }\n    public void setCorreo(String correo) { this.correo = correo; }\n\n    public String getCarrera() { return carrera; }\n    public void setCarrera(String carrera) { this.carrera = carrera; }\n}\n"},{"nombre":"EstudianteRepository.java","ruta":"mvc-estudiantes/src/main/java/pa/ac/unachi/mvcestudiantes/repository/EstudianteRepository.java","lenguaje":"java","lineas":11,"texto":"package pa.ac.unachi.mvcestudiantes.repository;\n\nimport java.util.List;\nimport org.springframework.data.jpa.repository.JpaRepository;\nimport pa.ac.unachi.mvcestudiantes.model.Estudiante;\n\npublic interface EstudianteRepository extends JpaRepository<Estudiante, Long> {\n    List<Estudiante> findByNombreContainingIgnoreCaseOrApellidoContainingIgnoreCase(\n            String nombre, String apellido);\n}\n"},{"nombre":"EstudianteService.java","ruta":"mvc-estudiantes/src/main/java/pa/ac/unachi/mvcestudiantes/service/EstudianteService.java","lenguaje":"java","lineas":39,"texto":"package pa.ac.unachi.mvcestudiantes.service;\n\nimport java.util.List;\nimport org.springframework.stereotype.Service;\nimport pa.ac.unachi.mvcestudiantes.model.Estudiante;\nimport pa.ac.unachi.mvcestudiantes.repository.EstudianteRepository;\n\n@Service\npublic class EstudianteService {\n\n    private final EstudianteRepository repository;\n\n    public EstudianteService(EstudianteRepository repository) {\n        this.repository = repository;\n    }\n\n    public List<Estudiante> listar(String buscar) {\n        if (buscar == null || buscar.isBlank()) {\n            return repository.findAll();\n        }\n        return repository.findByNombreContainingIgnoreCaseOrApellidoContainingIgnoreCase(\n                buscar, buscar);\n    }\n\n    public Estudiante buscarPorId(Long id) {\n        return repository.findById(id)\n                .orElseThrow(() -> new IllegalArgumentException(\n                        \"No existe el estudiante con id \" + id));\n    }\n\n    public Estudiante guardar(Estudiante estudiante) {\n        return repository.save(estudiante);\n    }\n\n    public void eliminar(Long id) {\n        repository.deleteById(id);\n    }\n}\n"},{"nombre":"EstudianteController.java","ruta":"mvc-estudiantes/src/main/java/pa/ac/unachi/mvcestudiantes/controller/EstudianteController.java","lenguaje":"java","lineas":62,"texto":"package pa.ac.unachi.mvcestudiantes.controller;\n\nimport jakarta.validation.Valid;\nimport org.springframework.stereotype.Controller;\nimport org.springframework.ui.Model;\nimport org.springframework.validation.BindingResult;\nimport org.springframework.web.bind.annotation.*;\nimport pa.ac.unachi.mvcestudiantes.model.Estudiante;\nimport pa.ac.unachi.mvcestudiantes.service.EstudianteService;\n\n@Controller\n@RequestMapping(\"/estudiantes\")\npublic class EstudianteController {\n\n    private final EstudianteService service;\n\n    public EstudianteController(EstudianteService service) {\n        this.service = service;\n    }\n\n    @GetMapping\n    public String listar(@RequestParam(required = false) String buscar, Model model) {\n        model.addAttribute(\"estudiantes\", service.listar(buscar));\n        model.addAttribute(\"buscar\", buscar == null ? \"\" : buscar);\n        return \"estudiantes/lista\";\n    }\n\n    @GetMapping(\"/nuevo\")\n    public String nuevo(Model model) {\n        model.addAttribute(\"estudiante\", new Estudiante());\n        model.addAttribute(\"titulo\", \"Nuevo estudiante\");\n        return \"estudiantes/formulario\";\n    }\n\n    @PostMapping(\"/guardar\")\n    public String guardar(@Valid @ModelAttribute Estudiante estudiante,\n                          BindingResult result,\n                          Model model) {\n        if (result.hasErrors()) {\n            model.addAttribute(\"titulo\",\n                    estudiante.getId() == null ? \"Nuevo estudiante\" : \"Editar estudiante\");\n            return \"estudiantes/formulario\";\n        }\n\n        service.guardar(estudiante);\n        return \"redirect:/estudiantes\";\n    }\n\n    @GetMapping(\"/editar/{id}\")\n    public String editar(@PathVariable Long id, Model model) {\n        model.addAttribute(\"estudiante\", service.buscarPorId(id));\n        model.addAttribute(\"titulo\", \"Editar estudiante\");\n        return \"estudiantes/formulario\";\n    }\n\n    @GetMapping(\"/eliminar/{id}\")\n    public String eliminar(@PathVariable Long id) {\n        service.eliminar(id);\n        return \"redirect:/estudiantes\";\n    }\n}\n"},{"nombre":"lista.html","ruta":"mvc-estudiantes/src/main/resources/templates/estudiantes/lista.html","lenguaje":"xml","lineas":87,"texto":"<!DOCTYPE html>\n<html lang=\"es\" xmlns:th=\"http://www.thymeleaf.org\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>Estudiantes</title>\n    <link href=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/css/bootstrap.min.css\" rel=\"stylesheet\">\n</head>\n<body class=\"bg-light\">\n\n<nav class=\"navbar navbar-dark bg-dark mb-4\">\n    <div class=\"container\">\n        <span class=\"navbar-brand\">UNACHI · Ejemplo MVC</span>\n    </div>\n</nav>\n\n<div class=\"container\">\n    <div class=\"d-flex justify-content-between align-items-center mb-3\">\n        <div>\n            <h1 class=\"h3\">Estudiantes</h1>\n            <p class=\"text-muted mb-0\">CRUD con Spring MVC, Thymeleaf y MariaDB</p>\n        </div>\n        <a class=\"btn btn-primary\" th:href=\"@{/estudiantes/nuevo}\">\n            Nuevo estudiante\n        </a>\n    </div>\n\n    <form class=\"row g-2 mb-3\" method=\"get\" th:action=\"@{/estudiantes}\">\n        <div class=\"col-md-9\">\n            <input class=\"form-control\" type=\"text\" name=\"buscar\"\n                   th:value=\"${buscar}\"\n                   placeholder=\"Buscar por nombre o apellido\">\n        </div>\n        <div class=\"col-md-3 d-grid\">\n            <button class=\"btn btn-outline-secondary\" type=\"submit\">Buscar</button>\n        </div>\n    </form>\n\n    <div class=\"card shadow-sm\">\n        <div class=\"table-responsive\">\n            <table class=\"table table-hover align-middle mb-0\">\n                <thead class=\"table-dark\">\n                <tr>\n                    <th>ID</th>\n                    <th>Cédula</th>\n                    <th>Nombre</th>\n                    <th>Apellido</th>\n                    <th>Correo</th>\n                    <th>Carrera</th>\n                    <th style=\"width: 170px;\">Acciones</th>\n                </tr>\n                </thead>\n                <tbody>\n                <tr th:each=\"e : ${estudiantes}\">\n                    <td th:text=\"${e.id}\"></td>\n                    <td th:text=\"${e.cedula}\"></td>\n                    <td th:text=\"${e.nombre}\"></td>\n                    <td th:text=\"${e.apellido}\"></td>\n                    <td th:text=\"${e.correo}\"></td>\n                    <td th:text=\"${e.carrera}\"></td>\n                    <td>\n                        <a class=\"btn btn-sm btn-warning\"\n                           th:href=\"@{/estudiantes/editar/{id}(id=${e.id})}\">\n                            Editar\n                        </a>\n                        <a class=\"btn btn-sm btn-danger\"\n                           th:href=\"@{/estudiantes/eliminar/{id}(id=${e.id})}\"\n                           onclick=\"return confirm('¿Desea eliminar este estudiante?')\">\n                            Eliminar\n                        </a>\n                    </td>\n                </tr>\n\n                <tr th:if=\"${#lists.isEmpty(estudiantes)}\">\n                    <td colspan=\"7\" class=\"text-center py-4 text-muted\">\n                        No hay estudiantes registrados.\n                    </td>\n                </tr>\n                </tbody>\n            </table>\n        </div>\n    </div>\n</div>\n\n</body>\n</html>\n"},{"nombre":"formulario.html","ruta":"mvc-estudiantes/src/main/resources/templates/estudiantes/formulario.html","lenguaje":"xml","lineas":76,"texto":"<!DOCTYPE html>\n<html lang=\"es\" xmlns:th=\"http://www.thymeleaf.org\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title th:text=\"${titulo}\">Estudiante</title>\n    <link href=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/css/bootstrap.min.css\" rel=\"stylesheet\">\n</head>\n<body class=\"bg-light\">\n\n<div class=\"container py-5\">\n    <div class=\"row justify-content-center\">\n        <div class=\"col-lg-8\">\n            <div class=\"card shadow-sm\">\n                <div class=\"card-body p-4\">\n                    <h1 class=\"h3 mb-4\" th:text=\"${titulo}\"></h1>\n\n                    <form th:action=\"@{/estudiantes/guardar}\"\n                          th:object=\"${estudiante}\" method=\"post\">\n\n                        <input type=\"hidden\" th:field=\"*{id}\">\n\n                        <div class=\"mb-3\">\n                            <label class=\"form-label\">Cédula</label>\n                            <input class=\"form-control\" th:field=\"*{cedula}\">\n                            <div class=\"text-danger small\"\n                                 th:if=\"${#fields.hasErrors('cedula')}\"\n                                 th:errors=\"*{cedula}\"></div>\n                        </div>\n\n                        <div class=\"row\">\n                            <div class=\"col-md-6 mb-3\">\n                                <label class=\"form-label\">Nombre</label>\n                                <input class=\"form-control\" th:field=\"*{nombre}\">\n                                <div class=\"text-danger small\"\n                                     th:if=\"${#fields.hasErrors('nombre')}\"\n                                     th:errors=\"*{nombre}\"></div>\n                            </div>\n\n                            <div class=\"col-md-6 mb-3\">\n                                <label class=\"form-label\">Apellido</label>\n                                <input class=\"form-control\" th:field=\"*{apellido}\">\n                                <div class=\"text-danger small\"\n                                     th:if=\"${#fields.hasErrors('apellido')}\"\n                                     th:errors=\"*{apellido}\"></div>\n                            </div>\n                        </div>\n\n                        <div class=\"mb-3\">\n                            <label class=\"form-label\">Correo</label>\n                            <input class=\"form-control\" type=\"email\" th:field=\"*{correo}\">\n                            <div class=\"text-danger small\"\n                                 th:if=\"${#fields.hasErrors('correo')}\"\n                                 th:errors=\"*{correo}\"></div>\n                        </div>\n\n                        <div class=\"mb-4\">\n                            <label class=\"form-label\">Carrera</label>\n                            <input class=\"form-control\" th:field=\"*{carrera}\">\n                            <div class=\"text-danger small\"\n                                 th:if=\"${#fields.hasErrors('carrera')}\"\n                                 th:errors=\"*{carrera}\"></div>\n                        </div>\n\n                        <button class=\"btn btn-primary\" type=\"submit\">Guardar</button>\n                        <a class=\"btn btn-secondary\" th:href=\"@{/estudiantes}\">Cancelar</a>\n                    </form>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>\n\n</body>\n</html>\n"},{"nombre":"application.properties","ruta":"mvc-estudiantes/src/main/resources/application.properties","lenguaje":"properties","lineas":16,"texto":"spring.application.name=mvc-estudiantes\n\nserver.port=8080\n\nspring.datasource.url=jdbc:mariadb://localhost:3306/mvc_unachi\nspring.datasource.username=mvc_user\nspring.datasource.password=<tu-contraseña-local>\nspring.datasource.driver-class-name=org.mariadb.jdbc.Driver\n\nspring.jpa.hibernate.ddl-auto=update\nspring.jpa.show-sql=true\nspring.jpa.properties.hibernate.format_sql=true\nspring.jpa.open-in-view=false\n\nspring.thymeleaf.cache=false\n"},{"nombre":"database.sql","ruta":"mvc-estudiantes/database.sql","lenguaje":"sql","lineas":26,"texto":"CREATE DATABASE IF NOT EXISTS mvc_unachi\n  CHARACTER SET utf8mb4\n  COLLATE utf8mb4_unicode_ci;\n\nCREATE USER IF NOT EXISTS 'mvc_user'@'localhost'\nIDENTIFIED BY 'MVC2026*';\n\nGRANT ALL PRIVILEGES ON mvc_unachi.* TO 'mvc_user'@'localhost';\nFLUSH PRIVILEGES;\n\nUSE mvc_unachi;\n\nCREATE TABLE IF NOT EXISTS estudiantes (\n    id BIGINT AUTO_INCREMENT PRIMARY KEY,\n    cedula VARCHAR(20) NOT NULL UNIQUE,\n    nombre VARCHAR(80) NOT NULL,\n    apellido VARCHAR(80) NOT NULL,\n    correo VARCHAR(120) NOT NULL,\n    carrera VARCHAR(120) NOT NULL\n);\n\nINSERT INTO estudiantes (cedula, nombre, apellido, correo, carrera)\nVALUES\n('4-123-456', 'Ana', 'González', 'ana.gonzalez@ejemplo.com', 'Ingeniería de Software'),\n('4-234-567', 'Carlos', 'Rodríguez', 'carlos.rodriguez@ejemplo.com', 'Ingeniería de Sistemas');\n"}],"lab5":[{"nombre":"Articulo.java","ruta":"gestion-inventario-jsp/src/main/java/com/unachi/inventario/modelo/Articulo.java","lenguaje":"java","lineas":46,"texto":"package com.unachi.inventario.modelo;\n\n/**\n * Entidad Articulo.\n * Campos: id, codigoBarra, nombre.\n */\npublic class Articulo {\n\n    private int id;\n    private String codigoBarra;\n    private String nombre;\n\n    public Articulo() {\n    }\n\n    public Articulo(int id, String codigoBarra, String nombre) {\n        this.id = id;\n        this.codigoBarra = codigoBarra;\n        this.nombre = nombre;\n    }\n\n    public int getId() {\n        return id;\n    }\n\n    public void setId(int id) {\n        this.id = id;\n    }\n\n    public String getCodigoBarra() {\n        return codigoBarra;\n    }\n\n    public void setCodigoBarra(String codigoBarra) {\n        this.codigoBarra = codigoBarra;\n    }\n\n    public String getNombre() {\n        return nombre;\n    }\n\n    public void setNombre(String nombre) {\n        this.nombre = nombre;\n    }\n}\n"},{"nombre":"Existencia.java","ruta":"gestion-inventario-jsp/src/main/java/com/unachi/inventario/modelo/Existencia.java","lenguaje":"java","lineas":75,"texto":"package com.unachi.inventario.modelo;\n\n/**\n * Entidad Existencia.\n * Campos solicitados: id, cantidadExistencia.\n *\n * NOTA: se agrega articuloId como llave foránea hacia Articulo, ya que una\n * existencia siempre pertenece a un artículo concreto; sin este vínculo no\n * sería posible saber de qué artículo es la cantidad registrada.\n *\n * Los campos nombreArticulo y codigoBarraArticulo son transitorios (no se\n * guardan en la tabla existencia): se llenan solo para mostrar información\n * legible en las pantallas de listado, evitando así hacer una segunda\n * consulta desde la capa de presentación.\n */\npublic class Existencia {\n\n    private int id;\n    private int articuloId;\n    private int cantidadExistencia;\n\n    // Campos de solo lectura para mostrar en pantalla (no se persisten)\n    private String nombreArticulo;\n    private String codigoBarraArticulo;\n\n    public Existencia() {\n    }\n\n    public Existencia(int id, int articuloId, int cantidadExistencia) {\n        this.id = id;\n        this.articuloId = articuloId;\n        this.cantidadExistencia = cantidadExistencia;\n    }\n\n    public int getId() {\n        return id;\n    }\n\n    public void setId(int id) {\n        this.id = id;\n    }\n\n    public int getArticuloId() {\n        return articuloId;\n    }\n\n    public void setArticuloId(int articuloId) {\n        this.articuloId = articuloId;\n    }\n\n    public int getCantidadExistencia() {\n        return cantidadExistencia;\n    }\n\n    public void setCantidadExistencia(int cantidadExistencia) {\n        this.cantidadExistencia = cantidadExistencia;\n    }\n\n    public String getNombreArticulo() {\n        return nombreArticulo;\n    }\n\n    public void setNombreArticulo(String nombreArticulo) {\n        this.nombreArticulo = nombreArticulo;\n    }\n\n    public String getCodigoBarraArticulo() {\n        return codigoBarraArticulo;\n    }\n\n    public void setCodigoBarraArticulo(String codigoBarraArticulo) {\n        this.codigoBarraArticulo = codigoBarraArticulo;\n    }\n}\n"},{"nombre":"ConexionBD.java","ruta":"gestion-inventario-jsp/src/main/java/com/unachi/inventario/datos/ConexionBD.java","lenguaje":"java","lineas":37,"texto":"package com.unachi.inventario.datos;\n\nimport java.sql.Connection;\nimport java.sql.DriverManager;\nimport java.sql.SQLException;\n\n/**\n * Capa de Datos — utilidad de conexión JDBC.\n *\n * Centraliza la configuración de acceso a la base de datos para que\n * los DAO no repitan esta lógica. Ajusta URL, USUARIO y PASSWORD según\n * tu entorno (local, AWS RDS, etc.).\n */\npublic final class ConexionBD {\n\n    private static final String URL =\n            \"jdbc:mysql://localhost:3306/inventario_db?useSSL=false&serverTimezone=UTC&characterEncoding=UTF-8\";\n    private static final String USUARIO = \"root\";\n    private static final String PASSWORD = \"\";\n\n    static {\n        try {\n            Class.forName(\"com.mysql.cj.jdbc.Driver\");\n        } catch (ClassNotFoundException e) {\n            throw new RuntimeException(\"No se encontró el driver JDBC de MySQL en el classpath.\", e);\n        }\n    }\n\n    private ConexionBD() {\n        // Clase utilitaria: no se instancia.\n    }\n\n    public static Connection obtenerConexion() throws SQLException {\n        return DriverManager.getConnection(URL, USUARIO, PASSWORD);\n    }\n}\n"},{"nombre":"ArticuloDAO.java","ruta":"gestion-inventario-jsp/src/main/java/com/unachi/inventario/datos/ArticuloDAO.java","lenguaje":"java","lineas":123,"texto":"package com.unachi.inventario.datos;\n\nimport com.unachi.inventario.modelo.Articulo;\n\nimport java.sql.Connection;\nimport java.sql.PreparedStatement;\nimport java.sql.ResultSet;\nimport java.sql.SQLException;\nimport java.sql.Statement;\nimport java.util.ArrayList;\nimport java.util.List;\n\n/**\n * Capa de Datos — acceso a la tabla \"articulo\".\n * Solo contiene lógica de persistencia (SQL). Ninguna regla de negocio\n * debe vivir aquí: eso corresponde a la capa de negocio (ArticuloService).\n */\npublic class ArticuloDAO {\n\n    public void crear(Articulo articulo) throws SQLException {\n        String sql = \"INSERT INTO articulo (codigo_barra, nombre) VALUES (?, ?)\";\n        try (Connection con = ConexionBD.obtenerConexion();\n             PreparedStatement ps = con.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {\n\n            ps.setString(1, articulo.getCodigoBarra());\n            ps.setString(2, articulo.getNombre());\n            ps.executeUpdate();\n\n            try (ResultSet rs = ps.getGeneratedKeys()) {\n                if (rs.next()) {\n                    articulo.setId(rs.getInt(1));\n                }\n            }\n        }\n    }\n\n    public List<Articulo> listarTodos() throws SQLException {\n        List<Articulo> lista = new ArrayList<>();\n        String sql = \"SELECT id, codigo_barra, nombre FROM articulo ORDER BY nombre\";\n\n        try (Connection con = ConexionBD.obtenerConexion();\n             PreparedStatement ps = con.prepareStatement(sql);\n             ResultSet rs = ps.executeQuery()) {\n\n            while (rs.next()) {\n                lista.add(mapearArticulo(rs));\n            }\n        }\n        return lista;\n    }\n\n    public Articulo buscarPorId(int id) throws SQLException {\n        String sql = \"SELECT id, codigo_barra, nombre FROM articulo WHERE id = ?\";\n\n        try (Connection con = ConexionBD.obtenerConexion();\n             PreparedStatement ps = con.prepareStatement(sql)) {\n\n            ps.setInt(1, id);\n            try (ResultSet rs = ps.executeQuery()) {\n                if (rs.next()) {\n                    return mapearArticulo(rs);\n                }\n            }\n        }\n        return null;\n    }\n\n    /**\n     * Verifica si ya existe un artículo con el código de barra dado.\n     * @param idExcluir si no es null, excluye ese id de la búsqueda\n     *                  (útil al validar durante una edición).\n     */\n    public boolean existeCodigoBarra(String codigoBarra, Integer idExcluir) throws SQLException {\n        String sql = \"SELECT COUNT(*) FROM articulo WHERE codigo_barra = ?\"\n                + (idExcluir != null ? \" AND id <> ?\" : \"\");\n\n        try (Connection con = ConexionBD.obtenerConexion();\n             PreparedStatement ps = con.prepareStatement(sql)) {\n\n            ps.setString(1, codigoBarra);\n            if (idExcluir != null) {\n                ps.setInt(2, idExcluir);\n            }\n            try (ResultSet rs = ps.executeQuery()) {\n                rs.next();\n                return rs.getInt(1) > 0;\n            }\n        }\n    }\n\n    public void actualizar(Articulo articulo) throws SQLException {\n        String sql = \"UPDATE articulo SET codigo_barra = ?, nombre = ? WHERE id = ?\";\n\n        try (Connection con = ConexionBD.obtenerConexion();\n             PreparedStatement ps = con.prepareStatement(sql)) {\n\n            ps.setString(1, articulo.getCodigoBarra());\n            ps.setString(2, articulo.getNombre());\n            ps.setInt(3, articulo.getId());\n            ps.executeUpdate();\n        }\n    }\n\n    public void eliminar(int id) throws SQLException {\n        String sql = \"DELETE FROM articulo WHERE id = ?\";\n\n        try (Connection con = ConexionBD.obtenerConexion();\n             PreparedStatement ps = con.prepareStatement(sql)) {\n\n            ps.setInt(1, id);\n            ps.executeUpdate();\n        }\n    }\n\n    private Articulo mapearArticulo(ResultSet rs) throws SQLException {\n        Articulo articulo = new Articulo();\n        articulo.setId(rs.getInt(\"id\"));\n        articulo.setCodigoBarra(rs.getString(\"codigo_barra\"));\n        articulo.setNombre(rs.getString(\"nombre\"));\n        return articulo;\n    }\n}\n"},{"nombre":"ExistenciaDAO.java","ruta":"gestion-inventario-jsp/src/main/java/com/unachi/inventario/datos/ExistenciaDAO.java","lenguaje":"java","lineas":109,"texto":"package com.unachi.inventario.datos;\n\nimport com.unachi.inventario.modelo.Existencia;\n\nimport java.sql.Connection;\nimport java.sql.PreparedStatement;\nimport java.sql.ResultSet;\nimport java.sql.SQLException;\nimport java.sql.Statement;\nimport java.util.ArrayList;\nimport java.util.List;\n\n/**\n * Capa de Datos — acceso a la tabla \"existencia\".\n * Al igual que ArticuloDAO, solo contiene sentencias SQL. Las reglas de\n * negocio (por ejemplo, no permitir una salida mayor a la existencia\n * disponible) se validan en ExistenciaService, no aquí.\n */\npublic class ExistenciaDAO {\n\n    public void crear(Existencia existencia) throws SQLException {\n        String sql = \"INSERT INTO existencia (articulo_id, cantidad_existencia) VALUES (?, ?)\";\n\n        try (Connection con = ConexionBD.obtenerConexion();\n             PreparedStatement ps = con.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {\n\n            ps.setInt(1, existencia.getArticuloId());\n            ps.setInt(2, existencia.getCantidadExistencia());\n            ps.executeUpdate();\n\n            try (ResultSet rs = ps.getGeneratedKeys()) {\n                if (rs.next()) {\n                    existencia.setId(rs.getInt(1));\n                }\n            }\n        }\n    }\n\n    public Existencia buscarPorArticulo(int articuloId) throws SQLException {\n        String sql = \"SELECT e.id, e.articulo_id, e.cantidad_existencia, a.nombre, a.codigo_barra \"\n                + \"FROM existencia e \"\n                + \"JOIN articulo a ON a.id = e.articulo_id \"\n                + \"WHERE e.articulo_id = ?\";\n\n        try (Connection con = ConexionBD.obtenerConexion();\n             PreparedStatement ps = con.prepareStatement(sql)) {\n\n            ps.setInt(1, articuloId);\n            try (ResultSet rs = ps.executeQuery()) {\n                if (rs.next()) {\n                    return mapearExistencia(rs);\n                }\n            }\n        }\n        return null;\n    }\n\n    public List<Existencia> listarTodas() throws SQLException {\n        List<Existencia> lista = new ArrayList<>();\n        String sql = \"SELECT e.id, e.articulo_id, e.cantidad_existencia, a.nombre, a.codigo_barra \"\n                + \"FROM existencia e \"\n                + \"JOIN articulo a ON a.id = e.articulo_id \"\n                + \"ORDER BY a.nombre\";\n\n        try (Connection con = ConexionBD.obtenerConexion();\n             PreparedStatement ps = con.prepareStatement(sql);\n             ResultSet rs = ps.executeQuery()) {\n\n            while (rs.next()) {\n                lista.add(mapearExistencia(rs));\n            }\n        }\n        return lista;\n    }\n\n    public void actualizarCantidad(int articuloId, int nuevaCantidad) throws SQLException {\n        String sql = \"UPDATE existencia SET cantidad_existencia = ? WHERE articulo_id = ?\";\n\n        try (Connection con = ConexionBD.obtenerConexion();\n             PreparedStatement ps = con.prepareStatement(sql)) {\n\n            ps.setInt(1, nuevaCantidad);\n            ps.setInt(2, articuloId);\n            ps.executeUpdate();\n        }\n    }\n\n    public void eliminarPorArticulo(int articuloId) throws SQLException {\n        String sql = \"DELETE FROM existencia WHERE articulo_id = ?\";\n\n        try (Connection con = ConexionBD.obtenerConexion();\n             PreparedStatement ps = con.prepareStatement(sql)) {\n\n            ps.setInt(1, articuloId);\n            ps.executeUpdate();\n        }\n    }\n\n    private Existencia mapearExistencia(ResultSet rs) throws SQLException {\n        Existencia existencia = new Existencia();\n        existencia.setId(rs.getInt(\"id\"));\n        existencia.setArticuloId(rs.getInt(\"articulo_id\"));\n        existencia.setCantidadExistencia(rs.getInt(\"cantidad_existencia\"));\n        existencia.setNombreArticulo(rs.getString(\"nombre\"));\n        existencia.setCodigoBarraArticulo(rs.getString(\"codigo_barra\"));\n        return existencia;\n    }\n}\n"},{"nombre":"ArticuloService.java","ruta":"gestion-inventario-jsp/src/main/java/com/unachi/inventario/negocio/ArticuloService.java","lenguaje":"java","lineas":77,"texto":"package com.unachi.inventario.negocio;\n\nimport com.unachi.inventario.datos.ArticuloDAO;\nimport com.unachi.inventario.datos.ExistenciaDAO;\nimport com.unachi.inventario.modelo.Articulo;\nimport com.unachi.inventario.modelo.Existencia;\n\nimport java.sql.SQLException;\nimport java.util.List;\n\n/**\n * Capa de Negocio — reglas del módulo \"Gestión de Artículos\".\n *\n * Reglas implementadas:\n *  - El nombre y el código de barra son obligatorios.\n *  - El código de barra debe ser único en el catálogo.\n *  - Al crear un artículo, se inicializa automáticamente su registro de\n *    existencia en cero (todo artículo debe tener una existencia asociada).\n *  - No se puede eliminar un artículo que aún tiene existencias mayores a cero.\n */\npublic class ArticuloService {\n\n    private final ArticuloDAO articuloDAO = new ArticuloDAO();\n    private final ExistenciaDAO existenciaDAO = new ExistenciaDAO();\n\n    public List<Articulo> listar() throws SQLException {\n        return articuloDAO.listarTodos();\n    }\n\n    public Articulo buscarPorId(int id) throws SQLException {\n        return articuloDAO.buscarPorId(id);\n    }\n\n    public void crear(Articulo articulo) throws SQLException, NegocioException {\n        validar(articulo, null);\n\n        articuloDAO.crear(articulo);\n\n        // Todo artículo nuevo inicia con existencia en cero.\n        Existencia existenciaInicial = new Existencia();\n        existenciaInicial.setArticuloId(articulo.getId());\n        existenciaInicial.setCantidadExistencia(0);\n        existenciaDAO.crear(existenciaInicial);\n    }\n\n    public void modificar(Articulo articulo) throws SQLException, NegocioException {\n        validar(articulo, articulo.getId());\n        articuloDAO.actualizar(articulo);\n    }\n\n    public void eliminar(int id) throws SQLException, NegocioException {\n        Existencia existencia = existenciaDAO.buscarPorArticulo(id);\n\n        if (existencia != null && existencia.getCantidadExistencia() > 0) {\n            throw new NegocioException(\n                    \"No se puede eliminar el artículo porque aún tiene existencias registradas (\"\n                            + existencia.getCantidadExistencia() + \" unidades).\"\n            );\n        }\n\n        existenciaDAO.eliminarPorArticulo(id);\n        articuloDAO.eliminar(id);\n    }\n\n    private void validar(Articulo articulo, Integer idExcluir) throws SQLException, NegocioException {\n        if (articulo.getNombre() == null || articulo.getNombre().trim().isEmpty()) {\n            throw new NegocioException(\"El nombre del artículo es obligatorio.\");\n        }\n        if (articulo.getCodigoBarra() == null || articulo.getCodigoBarra().trim().isEmpty()) {\n            throw new NegocioException(\"El código de barra es obligatorio.\");\n        }\n        if (articuloDAO.existeCodigoBarra(articulo.getCodigoBarra(), idExcluir)) {\n            throw new NegocioException(\"Ya existe un artículo registrado con ese código de barra.\");\n        }\n    }\n}\n"},{"nombre":"ExistenciaService.java","ruta":"gestion-inventario-jsp/src/main/java/com/unachi/inventario/negocio/ExistenciaService.java","lenguaje":"java","lineas":67,"texto":"package com.unachi.inventario.negocio;\n\nimport com.unachi.inventario.datos.ExistenciaDAO;\nimport com.unachi.inventario.modelo.Existencia;\n\nimport java.sql.SQLException;\nimport java.util.List;\n\n/**\n * Capa de Negocio — reglas del módulo \"Gestión de Existencias\".\n *\n * Reglas implementadas:\n *  - La cantidad de una entrada o salida debe ser mayor a cero.\n *  - No se puede registrar una salida mayor a la existencia disponible\n *    (esta es la regla que evita que el inventario quede en negativo).\n *  - Toda entrada/salida se aplica sobre el registro de existencia\n *    asociado al artículo (relación 1 a 1 entre Articulo y Existencia).\n */\npublic class ExistenciaService {\n\n    private final ExistenciaDAO existenciaDAO = new ExistenciaDAO();\n\n    public List<Existencia> listar() throws SQLException {\n        return existenciaDAO.listarTodas();\n    }\n\n    public Existencia buscarPorArticulo(int articuloId) throws SQLException {\n        return existenciaDAO.buscarPorArticulo(articuloId);\n    }\n\n    public void registrarEntrada(int articuloId, int cantidad) throws SQLException, NegocioException {\n        if (cantidad <= 0) {\n            throw new NegocioException(\"La cantidad de entrada debe ser mayor a cero.\");\n        }\n\n        Existencia existencia = obtenerExistenciaObligatoria(articuloId);\n        int nuevaCantidad = existencia.getCantidadExistencia() + cantidad;\n        existenciaDAO.actualizarCantidad(articuloId, nuevaCantidad);\n    }\n\n    public void registrarSalida(int articuloId, int cantidad) throws SQLException, NegocioException {\n        if (cantidad <= 0) {\n            throw new NegocioException(\"La cantidad de salida debe ser mayor a cero.\");\n        }\n\n        Existencia existencia = obtenerExistenciaObligatoria(articuloId);\n\n        if (cantidad > existencia.getCantidadExistencia()) {\n            throw new NegocioException(\n                    \"No hay suficiente existencia. Disponible: \"\n                            + existencia.getCantidadExistencia() + \" unidades.\"\n            );\n        }\n\n        int nuevaCantidad = existencia.getCantidadExistencia() - cantidad;\n        existenciaDAO.actualizarCantidad(articuloId, nuevaCantidad);\n    }\n\n    private Existencia obtenerExistenciaObligatoria(int articuloId) throws SQLException, NegocioException {\n        Existencia existencia = existenciaDAO.buscarPorArticulo(articuloId);\n        if (existencia == null) {\n            throw new NegocioException(\"El artículo seleccionado no tiene un registro de existencia asociado.\");\n        }\n        return existencia;\n    }\n}\n"},{"nombre":"ArticuloServlet.java","ruta":"gestion-inventario-jsp/src/main/java/com/unachi/inventario/presentacion/ArticuloServlet.java","lenguaje":"java","lineas":149,"texto":"package com.unachi.inventario.presentacion;\n\nimport com.unachi.inventario.modelo.Articulo;\nimport com.unachi.inventario.negocio.ArticuloService;\nimport com.unachi.inventario.negocio.NegocioException;\n\nimport jakarta.servlet.RequestDispatcher;\nimport jakarta.servlet.ServletException;\nimport jakarta.servlet.annotation.WebServlet;\nimport jakarta.servlet.http.HttpServlet;\nimport jakarta.servlet.http.HttpServletRequest;\nimport jakarta.servlet.http.HttpServletResponse;\nimport java.io.IOException;\nimport java.sql.SQLException;\n\n/**\n * Capa de Presentación — controlador HTTP del módulo \"Gestión de Artículos\".\n *\n * Este servlet NO contiene reglas de negocio ni SQL: solo recibe la\n * solicitud HTTP, delega en ArticuloService (capa de negocio) y decide\n * a qué JSP reenviar la respuesta.\n *\n * Acciones soportadas (parámetro \"accion\"):\n *   - listar   (por defecto)  -> GET  /articulos\n *   - nuevo                   -> GET  /articulos?accion=nuevo\n *   - editar                  -> GET  /articulos?accion=editar&id=..\n *   - eliminar                -> GET  /articulos?accion=eliminar&id=..\n *   - guardar (crear/editar)  -> POST /articulos\n */\n@WebServlet(\"/articulos\")\npublic class ArticuloServlet extends HttpServlet {\n\n    private final ArticuloService articuloService = new ArticuloService();\n\n    @Override\n    protected void doGet(HttpServletRequest request, HttpServletResponse response)\n            throws ServletException, IOException {\n\n        String accion = request.getParameter(\"accion\");\n        if (accion == null) {\n            accion = \"listar\";\n        }\n\n        try {\n            switch (accion) {\n                case \"nuevo\":\n                    mostrarFormulario(request, response, null);\n                    break;\n                case \"editar\":\n                    int id = Integer.parseInt(request.getParameter(\"id\"));\n                    Articulo articulo = articuloService.buscarPorId(id);\n                    mostrarFormulario(request, response, articulo);\n                    break;\n                case \"eliminar\":\n                    eliminar(request, response);\n                    break;\n                default:\n                    listar(request, response);\n            }\n        } catch (SQLException e) {\n            throw new ServletException(\"Error de base de datos en ArticuloServlet\", e);\n        }\n    }\n\n    @Override\n    protected void doPost(HttpServletRequest request, HttpServletResponse response)\n            throws ServletException, IOException {\n        guardar(request, response);\n    }\n\n    // ---------------------------------------------------------------\n    // Listar\n    // ---------------------------------------------------------------\n    private void listar(HttpServletRequest request, HttpServletResponse response)\n            throws ServletException, IOException, SQLException {\n\n        request.setAttribute(\"articulos\", articuloService.listar());\n        RequestDispatcher rd = request.getRequestDispatcher(\"/articulos/listar.jsp\");\n        rd.forward(request, response);\n    }\n\n    // ---------------------------------------------------------------\n    // Mostrar formulario (nuevo o editar)\n    // ---------------------------------------------------------------\n    private void mostrarFormulario(HttpServletRequest request, HttpServletResponse response, Articulo articulo)\n            throws ServletException, IOException {\n\n        request.setAttribute(\"articulo\", articulo);\n        RequestDispatcher rd = request.getRequestDispatcher(\"/articulos/formulario.jsp\");\n        rd.forward(request, response);\n    }\n\n    // ---------------------------------------------------------------\n    // Guardar (crear o modificar según venga o no el id)\n    // ---------------------------------------------------------------\n    private void guardar(HttpServletRequest request, HttpServletResponse response)\n            throws ServletException, IOException {\n\n        String idParam = request.getParameter(\"id\");\n        String codigoBarra = request.getParameter(\"codigoBarra\");\n        String nombre = request.getParameter(\"nombre\");\n\n        Articulo articulo = new Articulo();\n        articulo.setCodigoBarra(codigoBarra);\n        articulo.setNombre(nombre);\n\n        try {\n            if (idParam != null && !idParam.trim().isEmpty()) {\n                articulo.setId(Integer.parseInt(idParam));\n                articuloService.modificar(articulo);\n            } else {\n                articuloService.crear(articulo);\n            }\n            response.sendRedirect(request.getContextPath() + \"/articulos\");\n\n        } catch (NegocioException e) {\n            // Regla de negocio violada: se muestra el error en el mismo formulario.\n            request.setAttribute(\"error\", e.getMessage());\n            request.setAttribute(\"articulo\", articulo);\n            RequestDispatcher rd = request.getRequestDispatcher(\"/articulos/formulario.jsp\");\n            rd.forward(request, response);\n\n        } catch (SQLException e) {\n            throw new ServletException(\"Error de base de datos al guardar el artículo\", e);\n        }\n    }\n\n    // ---------------------------------------------------------------\n    // Eliminar\n    // ---------------------------------------------------------------\n    private void eliminar(HttpServletRequest request, HttpServletResponse response)\n            throws ServletException, IOException, SQLException {\n\n        int id = Integer.parseInt(request.getParameter(\"id\"));\n\n        try {\n            articuloService.eliminar(id);\n            response.sendRedirect(request.getContextPath() + \"/articulos\");\n\n        } catch (NegocioException e) {\n            // Ej.: intentar eliminar un artículo con existencias > 0.\n            request.setAttribute(\"error\", e.getMessage());\n            request.setAttribute(\"articulos\", articuloService.listar());\n            RequestDispatcher rd = request.getRequestDispatcher(\"/articulos/listar.jsp\");\n            rd.forward(request, response);\n        }\n    }\n}\n"},{"nombre":"ExistenciaServlet.java","ruta":"gestion-inventario-jsp/src/main/java/com/unachi/inventario/presentacion/ExistenciaServlet.java","lenguaje":"java","lineas":122,"texto":"package com.unachi.inventario.presentacion;\n\nimport com.unachi.inventario.negocio.ArticuloService;\nimport com.unachi.inventario.negocio.ExistenciaService;\nimport com.unachi.inventario.negocio.NegocioException;\n\nimport jakarta.servlet.RequestDispatcher;\nimport jakarta.servlet.ServletException;\nimport jakarta.servlet.annotation.WebServlet;\nimport jakarta.servlet.http.HttpServlet;\nimport jakarta.servlet.http.HttpServletRequest;\nimport jakarta.servlet.http.HttpServletResponse;\nimport java.io.IOException;\nimport java.sql.SQLException;\n\n/**\n * Capa de Presentación — controlador HTTP del módulo \"Gestión de Existencias\".\n *\n * Acciones soportadas (parámetro \"accion\"):\n *   - listar     (por defecto) -> GET  /existencias\n *   - movimiento               -> GET  /existencias?accion=movimiento\n *   - registrar (entrada/salida) -> POST /existencias\n */\n@WebServlet(\"/existencias\")\npublic class ExistenciaServlet extends HttpServlet {\n\n    private final ExistenciaService existenciaService = new ExistenciaService();\n    private final ArticuloService articuloService = new ArticuloService();\n\n    @Override\n    protected void doGet(HttpServletRequest request, HttpServletResponse response)\n            throws ServletException, IOException {\n\n        String accion = request.getParameter(\"accion\");\n        if (accion == null) {\n            accion = \"listar\";\n        }\n\n        try {\n            switch (accion) {\n                case \"movimiento\":\n                    mostrarFormularioMovimiento(request, response, null);\n                    break;\n                default:\n                    listar(request, response);\n            }\n        } catch (SQLException e) {\n            throw new ServletException(\"Error de base de datos en ExistenciaServlet\", e);\n        }\n    }\n\n    @Override\n    protected void doPost(HttpServletRequest request, HttpServletResponse response)\n            throws ServletException, IOException {\n        registrarMovimiento(request, response);\n    }\n\n    // ---------------------------------------------------------------\n    // Listar existencias\n    // ---------------------------------------------------------------\n    private void listar(HttpServletRequest request, HttpServletResponse response)\n            throws ServletException, IOException, SQLException {\n\n        request.setAttribute(\"existencias\", existenciaService.listar());\n        RequestDispatcher rd = request.getRequestDispatcher(\"/existencias/listar.jsp\");\n        rd.forward(request, response);\n    }\n\n    // ---------------------------------------------------------------\n    // Formulario de entrada / salida\n    // ---------------------------------------------------------------\n    private void mostrarFormularioMovimiento(HttpServletRequest request, HttpServletResponse response, String error)\n            throws ServletException, IOException, SQLException {\n\n        request.setAttribute(\"articulos\", articuloService.listar());\n        if (error != null) {\n            request.setAttribute(\"error\", error);\n        }\n        RequestDispatcher rd = request.getRequestDispatcher(\"/existencias/movimiento.jsp\");\n        rd.forward(request, response);\n    }\n\n    // ---------------------------------------------------------------\n    // Registrar entrada o salida\n    // ---------------------------------------------------------------\n    private void registrarMovimiento(HttpServletRequest request, HttpServletResponse response)\n            throws ServletException, IOException {\n\n        try {\n            int articuloId = Integer.parseInt(request.getParameter(\"articuloId\"));\n            int cantidad = Integer.parseInt(request.getParameter(\"cantidad\"));\n            String tipo = request.getParameter(\"tipo\"); // \"entrada\" o \"salida\"\n\n            if (\"entrada\".equals(tipo)) {\n                existenciaService.registrarEntrada(articuloId, cantidad);\n            } else {\n                existenciaService.registrarSalida(articuloId, cantidad);\n            }\n\n            response.sendRedirect(request.getContextPath() + \"/existencias\");\n\n        } catch (NumberFormatException e) {\n            manejarError(request, response, \"Debe ingresar valores numéricos válidos.\");\n\n        } catch (NegocioException e) {\n            manejarError(request, response, e.getMessage());\n\n        } catch (SQLException e) {\n            throw new ServletException(\"Error de base de datos al registrar el movimiento\", e);\n        }\n    }\n\n    private void manejarError(HttpServletRequest request, HttpServletResponse response, String mensaje)\n            throws ServletException, IOException {\n        try {\n            mostrarFormularioMovimiento(request, response, mensaje);\n        } catch (SQLException ex) {\n            throw new ServletException(\"Error de base de datos al recargar el formulario\", ex);\n        }\n    }\n}\n"},{"nombre":"listar.jsp","ruta":"gestion-inventario-jsp/src/main/webapp/articulos/listar.jsp","lenguaje":"xml","lineas":58,"texto":"<%@ page contentType=\"text/html;charset=UTF-8\" pageEncoding=\"UTF-8\" %>\n<%@ taglib uri=\"jakarta.tags.core\" prefix=\"c\" %>\n<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n    <meta charset=\"UTF-8\">\n    <title>Artículos — Inventario</title>\n    <link rel=\"stylesheet\" href=\"${pageContext.request.contextPath}/css/style.css\">\n</head>\n<body>\n<div class=\"contenedor\">\n    <header class=\"encabezado\">\n        <h1>Gestión de Artículos</h1>\n        <a class=\"boton boton-primario\" href=\"${pageContext.request.contextPath}/articulos?accion=nuevo\">\n            + Nuevo artículo\n        </a>\n    </header>\n\n    <c:if test=\"${not empty error}\">\n        <div class=\"alerta alerta-error\">${error}</div>\n    </c:if>\n\n    <table class=\"tabla\">\n        <thead>\n        <tr>\n            <th>Código de barra</th>\n            <th>Nombre</th>\n            <th>Acciones</th>\n        </tr>\n        </thead>\n        <tbody>\n        <c:forEach var=\"a\" items=\"${articulos}\">\n            <tr>\n                <td>${a.codigoBarra}</td>\n                <td>${a.nombre}</td>\n                <td class=\"acciones\">\n                    <a href=\"${pageContext.request.contextPath}/articulos?accion=editar&id=${a.id}\">Editar</a>\n                    <a href=\"${pageContext.request.contextPath}/articulos?accion=eliminar&id=${a.id}\"\n                       class=\"enlace-peligro\"\n                       onclick=\"return confirm('¿Eliminar este artículo?');\">Eliminar</a>\n                </td>\n            </tr>\n        </c:forEach>\n        <c:if test=\"${empty articulos}\">\n            <tr>\n                <td colspan=\"3\" class=\"vacio\">No hay artículos registrados.</td>\n            </tr>\n        </c:if>\n        </tbody>\n    </table>\n\n    <p class=\"enlace-volver\">\n        <a href=\"${pageContext.request.contextPath}/index.jsp\">&larr; Volver al menú principal</a>\n    </p>\n</div>\n</body>\n</html>\n"},{"nombre":"schema.sql","ruta":"gestion-inventario-jsp/db/schema.sql","lenguaje":"sql","lineas":39,"texto":"-- =====================================================================\n-- Sistema de Gestión de Inventario — Script de base de datos (MySQL)\n-- =====================================================================\n\nCREATE DATABASE IF NOT EXISTS inventario_db\n    CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;\n\nUSE inventario_db;\n\n-- Entidad Articulo: id, codigoBarra, nombre\nCREATE TABLE IF NOT EXISTS articulo (\n    id            INT AUTO_INCREMENT PRIMARY KEY,\n    codigo_barra  VARCHAR(50)  NOT NULL UNIQUE,\n    nombre        VARCHAR(150) NOT NULL\n);\n\n-- Entidad Existencia: id, cantidadExistencia\n-- (se agrega articulo_id como llave foránea; ver nota en Existencia.java)\nCREATE TABLE IF NOT EXISTS existencia (\n    id                    INT AUTO_INCREMENT PRIMARY KEY,\n    articulo_id           INT NOT NULL,\n    cantidad_existencia   INT NOT NULL DEFAULT 0,\n    CONSTRAINT fk_existencia_articulo\n        FOREIGN KEY (articulo_id) REFERENCES articulo(id)\n        ON DELETE CASCADE,\n    CONSTRAINT uq_existencia_articulo UNIQUE (articulo_id)\n);\n\n-- Datos de ejemplo (opcional, para probar la aplicación)\nINSERT INTO articulo (codigo_barra, nombre) VALUES\n    ('750001000001', 'Arroz 1kg'),\n    ('750001000002', 'Aceite vegetal 1L'),\n    ('750001000003', 'Azúcar 1kg');\n\nINSERT INTO existencia (articulo_id, cantidad_existencia) VALUES\n    (1, 50),\n    (2, 30),\n    (3, 0);\n"}],"lab7":[{"nombre":"Servidor.java","ruta":"prototipo-java21/src/main/java/Servidor.java","lenguaje":"java","lineas":164,"texto":"// Prototipo de servidor de reservas (Programación V, semana 9).\n// Solo usa clases incluidas en el JDK 21: no requiere Maven ni librerías.\n// Ejecutar:  java Servidor.java 4         (4 hilos de trabajo)\n//            java Servidor.java virtual   (un hilo virtual por solicitud)\nimport com.sun.net.httpserver.HttpExchange;\nimport com.sun.net.httpserver.HttpServer;\nimport java.io.IOException;\nimport java.io.OutputStream;\nimport java.net.InetSocketAddress;\nimport java.net.URI;\nimport java.nio.charset.StandardCharsets;\nimport java.time.LocalTime;\nimport java.util.*;\nimport java.util.concurrent.Executors;\nimport java.util.concurrent.atomic.AtomicInteger;\nimport java.util.regex.Matcher;\nimport java.util.regex.Pattern;\n\npublic class Servidor {\n\n    record Espacio(int id, String nombre, int capacidad) {\n        String json() { return String.format(\"{\\\"id\\\":%d,\\\"nombre\\\":\\\"%s\\\",\\\"capacidad\\\":%d}\", id, nombre, capacidad); }\n    }\n\n    record Reserva(int id, int espacioId, String fecha, String hora, String solicitante) {\n        String json() {\n            return String.format(\"{\\\"id\\\":%d,\\\"espacioId\\\":%d,\\\"fecha\\\":\\\"%s\\\",\\\"hora\\\":\\\"%s\\\",\\\"solicitante\\\":\\\"%s\\\"}\",\n                    id, espacioId, fecha, hora, solicitante);\n        }\n    }\n\n    static final List<Espacio> espacios = List.of(\n            new Espacio(1, \"Laboratorio de Cómputo 1\", 30),\n            new Espacio(2, \"Laboratorio de Cómputo 2\", 25),\n            new Espacio(3, \"Auditorio\", 120));\n    static final List<Reserva> reservas = new ArrayList<>();\n    static final AtomicInteger atendidas = new AtomicInteger();\n\n    public static void main(String[] args) throws IOException {\n        String modo = args.length > 0 ? args[0] : \"4\";\n        calibrar();\n        int puerto = Integer.parseInt(System.getenv().getOrDefault(\"PORT\", \"3000\"));\n        HttpServer servidor = HttpServer.create(new InetSocketAddress(puerto), 200);\n        servidor.createContext(\"/api/\", Servidor::atender);\n        if (modo.equals(\"virtual\")) {\n            servidor.setExecutor(Executors.newVirtualThreadPerTaskExecutor());\n        } else {\n            servidor.setExecutor(Executors.newFixedThreadPool(Integer.parseInt(modo)));\n        }\n        servidor.start();\n        System.out.println(\"Servidor de reservas en http://localhost:\" + puerto + \" (hilos: \" + modo\n                + \", núcleos: \" + Runtime.getRuntime().availableProcessors() + \")\");\n    }\n\n    static void atender(HttpExchange ex) throws IOException {\n        atendidas.incrementAndGet();\n        String metodo = ex.getRequestMethod();\n        URI uri = ex.getRequestURI();\n        String ruta = uri.getPath();\n        System.out.printf(\"%s  %-6s %s  [%s]%n\", LocalTime.now().toString().substring(0, 12), metodo, uri, Thread.currentThread().getName());\n        try {\n            if (metodo.equals(\"GET\") && ruta.equals(\"/api/espacios\")) {\n                responder(ex, 200, \"[\" + String.join(\",\", espacios.stream().map(Espacio::json).toList()) + \"]\");\n            } else if (metodo.equals(\"GET\") && ruta.equals(\"/api/reservas\")) {\n                synchronized (reservas) {\n                    responder(ex, 200, \"[\" + String.join(\",\", reservas.stream().map(Reserva::json).toList()) + \"]\");\n                }\n            } else if (metodo.equals(\"POST\") && ruta.equals(\"/api/reservas\")) {\n                crearReserva(ex);\n            } else if (metodo.equals(\"GET\") && ruta.equals(\"/api/lento\")) {\n                int ms = parametro(uri, \"ms\", 500);\n                Thread.sleep(ms); // simula esperar a la base de datos: el hilo queda ocupado esperando\n                responder(ex, 200, \"{\\\"tipo\\\":\\\"espera (E/S)\\\",\\\"ms\\\":\" + ms + \"}\");\n            } else if (metodo.equals(\"GET\") && ruta.equals(\"/api/bloqueante\")) {\n                int ms = parametro(uri, \"ms\", 500);\n                calculoPesado(ms); // simula un cálculo: el hilo ocupa un núcleo del procesador\n                responder(ex, 200, \"{\\\"tipo\\\":\\\"cálculo (CPU)\\\",\\\"ms\\\":\" + ms + \"}\");\n            } else if (metodo.equals(\"GET\") && ruta.equals(\"/api/estado\")) {\n                responder(ex, 200, \"{\\\"estado\\\":\\\"ok\\\",\\\"solicitudesAtendidas\\\":\" + atendidas.get() + \"}\");\n            } else {\n                responder(ex, 404, \"{\\\"error\\\":\\\"Ruta no encontrada\\\"}\");\n            }\n        } catch (InterruptedException e) {\n            responder(ex, 500, \"{\\\"error\\\":\\\"Interrumpido\\\"}\");\n        }\n    }\n\n    static void crearReserva(HttpExchange ex) throws IOException {\n        String cuerpo = new String(ex.getRequestBody().readAllBytes(), StandardCharsets.UTF_8);\n        Integer espacioId = numero(cuerpo, \"espacioId\");\n        String fecha = texto(cuerpo, \"fecha\"), hora = texto(cuerpo, \"hora\"), solicitante = texto(cuerpo, \"solicitante\");\n        if (espacioId == null || fecha == null || hora == null || solicitante == null) {\n            responder(ex, 400, \"{\\\"error\\\":\\\"espacioId, fecha, hora y solicitante son obligatorios\\\"}\");\n            return;\n        }\n        if (espacios.stream().noneMatch(e -> e.id() == espacioId)) {\n            responder(ex, 404, \"{\\\"error\\\":\\\"El espacio no existe\\\"}\");\n            return;\n        }\n        Reserva nueva;\n        // Sección crítica: solo un hilo a la vez puede verificar y guardar.\n        synchronized (reservas) {\n            boolean ocupado = reservas.stream().anyMatch(r ->\n                    r.espacioId() == espacioId && r.fecha().equals(fecha) && r.hora().equals(hora));\n            if (ocupado) {\n                responder(ex, 409, \"{\\\"error\\\":\\\"Ese espacio ya está reservado en esa fecha y hora\\\"}\");\n                return;\n            }\n            nueva = new Reserva(reservas.size() + 1, espacioId, fecha, hora, solicitante);\n            reservas.add(nueva);\n        }\n        responder(ex, 201, nueva.json());\n    }\n\n    // Cálculo pesado: una cantidad FIJA de trabajo que tarda unos 'ms' milisegundos\n    // si tiene un núcleo para él solo. Si varios hilos compiten por los núcleos, tarda más.\n    static volatile double resultado;\n    static long iteracionesPorMs = 1;\n\n    static void calcular(long iteraciones) {\n        double x = 0;\n        for (long i = 0; i < iteraciones; i++) { x += Math.sqrt(i); }\n        resultado = x;\n    }\n\n    static void calibrar() {\n        for (int i = 0; i < 5; i++) calcular(2_000_000); // calentar el compilador JIT\n        long t0 = System.nanoTime();\n        calcular(20_000_000);\n        long ms = Math.max(1, (System.nanoTime() - t0) / 1_000_000);\n        iteracionesPorMs = 20_000_000 / ms;\n    }\n\n    static void calculoPesado(int ms) { calcular(iteracionesPorMs * ms); }\n\n    static void responder(HttpExchange ex, int codigo, String json) throws IOException {\n        byte[] datos = json.getBytes(StandardCharsets.UTF_8);\n        ex.getResponseHeaders().set(\"Content-Type\", \"application/json; charset=utf-8\");\n        ex.sendResponseHeaders(codigo, datos.length);\n        try (OutputStream os = ex.getResponseBody()) { os.write(datos); }\n    }\n\n    // Lectura mínima de JSON plano (en la semana 12 usaremos una librería como Jackson).\n    static String texto(String json, String clave) {\n        Matcher m = Pattern.compile(\"\\\"\" + clave + \"\\\"\\\\s*:\\\\s*\\\"([^\\\"]*)\\\"\").matcher(json);\n        return m.find() ? m.group(1) : null;\n    }\n\n    static Integer numero(String json, String clave) {\n        Matcher m = Pattern.compile(\"\\\"\" + clave + \"\\\"\\\\s*:\\\\s*(-?\\\\d+)\").matcher(json);\n        return m.find() ? Integer.valueOf(m.group(1)) : null;\n    }\n\n    static int parametro(URI uri, String nombre, int defecto) {\n        String q = uri.getQuery();\n        if (q == null) return defecto;\n        for (String par : q.split(\"&\")) {\n            String[] kv = par.split(\"=\");\n            if (kv.length == 2 && kv[0].equals(nombre)) return Integer.parseInt(kv[1]);\n        }\n        return defecto;\n    }\n}\n"},{"nombre":"Cliente.java","ruta":"prototipo-java21/src/main/java/Cliente.java","lenguaje":"java","lineas":30,"texto":"// Cliente de consola: consulta los espacios y crea una reserva.\n// Ejecutar: java Cliente.java \"Nombre del solicitante\"\nimport java.net.ConnectException;\nimport java.net.URI;\nimport java.net.http.HttpClient;\nimport java.net.http.HttpRequest;\nimport java.net.http.HttpResponse;\n\npublic class Cliente {\n    public static void main(String[] args) throws Exception {\n        String base = System.getenv().getOrDefault(\"SERVIDOR\", \"http://localhost:3000\");\n        String solicitante = args.length > 0 ? args[0] : \"Estudiante\";\n        HttpClient http = HttpClient.newBuilder().version(HttpClient.Version.HTTP_1_1).build();\n        try {\n            HttpResponse<String> r1 = http.send(HttpRequest.newBuilder(URI.create(base + \"/api/espacios\")).build(),\n                    HttpResponse.BodyHandlers.ofString());\n            System.out.println(\"Espacios disponibles: \" + r1.body());\n\n            String json = String.format(\"{\\\"espacioId\\\":1,\\\"fecha\\\":\\\"2026-10-20\\\",\\\"hora\\\":\\\"07:00\\\",\\\"solicitante\\\":\\\"%s\\\"}\", solicitante);\n            HttpRequest post = HttpRequest.newBuilder(URI.create(base + \"/api/reservas\"))\n                    .header(\"Content-Type\", \"application/json\")\n                    .POST(HttpRequest.BodyPublishers.ofString(json)).build();\n            HttpResponse<String> r2 = http.send(post, HttpResponse.BodyHandlers.ofString());\n            System.out.println(\"Respuesta del servidor: \" + r2.statusCode() + \" \" + r2.body());\n        } catch (ConnectException e) {\n            System.out.println(\"No se pudo conectar con el servidor en \" + base + \". ¿Está encendido?\");\n        }\n    }\n}\n"},{"nombre":"Carga.java","ruta":"prototipo-java21/src/main/java/Carga.java","lenguaje":"java","lineas":51,"texto":"// Envía muchas solicitudes al mismo tiempo y mide cuánto tarda el servidor.\n// Ejecutar: java Carga.java <ruta> <cantidad>\n//   java Carga.java \"/api/lento?ms=500\" 20\n//   java Carga.java \"/api/bloqueante?ms=500\" 20\n//   java Carga.java reservas 10      (10 reservas simultáneas del mismo espacio y hora)\nimport java.net.URI;\nimport java.net.http.HttpClient;\nimport java.net.http.HttpRequest;\nimport java.net.http.HttpResponse;\nimport java.time.Duration;\nimport java.util.*;\nimport java.util.concurrent.CompletableFuture;\n\npublic class Carga {\n    public static void main(String[] args) {\n        String base = System.getenv().getOrDefault(\"SERVIDOR\", \"http://localhost:3000\");\n        String ruta = args.length > 0 ? args[0] : \"/api/lento?ms=500\";\n        int cantidad = args.length > 1 ? Integer.parseInt(args[1]) : 20;\n        HttpClient http = HttpClient.newBuilder().version(HttpClient.Version.HTTP_1_1)\n                .connectTimeout(Duration.ofSeconds(10)).build();\n\n        System.out.printf(\"Enviando %d solicitudes simultáneas a %s ...%n\", cantidad, ruta);\n        long inicio = System.currentTimeMillis();\n        List<CompletableFuture<long[]>> pendientes = new ArrayList<>();\n        for (int i = 1; i <= cantidad; i++) {\n            HttpRequest.Builder b;\n            if (ruta.equals(\"reservas\")) {\n                String json = \"{\\\"espacioId\\\":3,\\\"fecha\\\":\\\"2026-10-22\\\",\\\"hora\\\":\\\"09:00\\\",\\\"solicitante\\\":\\\"Cliente \" + i + \"\\\"}\";\n                b = HttpRequest.newBuilder(URI.create(base + \"/api/reservas\")).header(\"Content-Type\", \"application/json\")\n                        .POST(HttpRequest.BodyPublishers.ofString(json));\n            } else {\n                b = HttpRequest.newBuilder(URI.create(base + ruta));\n            }\n            long t0 = System.currentTimeMillis();\n            pendientes.add(http.sendAsync(b.timeout(Duration.ofSeconds(60)).build(), HttpResponse.BodyHandlers.discarding())\n                    .thenApply(r -> new long[]{r.statusCode(), System.currentTimeMillis() - t0})\n                    .exceptionally(e -> new long[]{-1, System.currentTimeMillis() - t0}));\n        }\n        List<long[]> res = pendientes.stream().map(CompletableFuture::join).toList();\n        long total = System.currentTimeMillis() - inicio;\n        LongSummaryStatistics t = res.stream().mapToLong(r -> r[1]).summaryStatistics();\n        Map<String, Integer> codigos = new TreeMap<>();\n        res.forEach(r -> codigos.merge(r[0] == -1 ? \"ERROR\" : String.valueOf(r[0]), 1, Integer::sum));\n        System.out.println(\"Tiempo total:            \" + total + \" ms\");\n        System.out.println(\"Respuesta más rápida:    \" + t.getMin() + \" ms\");\n        System.out.println(\"Respuesta más lenta:     \" + t.getMax() + \" ms\");\n        System.out.println(\"Promedio por solicitud:  \" + Math.round(t.getAverage()) + \" ms\");\n        System.out.println(\"Códigos de estado:       \" + codigos);\n    }\n}\n"}],"lab8":[{"nombre":"ServidorReservas.java","ruta":"ReservasLabAPI/src/reservas/servidor/ServidorReservas.java","lenguaje":"java","lineas":55,"texto":"package reservas.servidor;\n\nimport java.io.IOException;\nimport java.net.InetSocketAddress;\nimport java.util.concurrent.ExecutorService;\nimport java.util.concurrent.Executors;\n\nimport com.sun.net.httpserver.HttpServer;\n\nimport reservas.datos.RepositorioReservas;\nimport reservas.modelo.Reserva;\nimport reservas.negocio.ServicioReservas;\n\n/**\n * SERVIDOR de la arquitectura cliente-servidor.\n * Usa el HttpServer que viene incluido en el JDK (Java 6+), así no hace falta\n * instalar Spring Boot, Tomcat ni ningún JAR adicional.\n *\n * Ejecutar: java -cp build reservas.servidor.ServidorReservas\n */\npublic class ServidorReservas {\n\n    public static final int PUERTO = 8080;\n\n    // RNF-04 (Concurrencia): hasta 10 solicitudes atendidas en paralelo\n    private static final int HILOS = 10;\n\n    public static void main(String[] args) throws IOException {\n        // Ensamblado de capas: datos -> negocio -> servidor\n        RepositorioReservas repo = new RepositorioReservas();\n        ServicioReservas servicio = new ServicioReservas(repo);\n        cargarDatosDemo(servicio);\n\n        HttpServer server = HttpServer.create(new InetSocketAddress(PUERTO), 0);\n        server.createContext(\"/api/reservas\", new ReservasHandler(servicio));\n\n        ExecutorService pool = Executors.newFixedThreadPool(HILOS);\n        server.setExecutor(pool);\n        server.start();\n\n        System.out.println(\"==============================================\");\n        System.out.println(\" Servidor de Reservas de Laboratorios - UNACHI\");\n        System.out.println(\" Escuchando en http://localhost:\" + PUERTO + \"/api/reservas\");\n        System.out.println(\" Hilos de atención: \" + HILOS);\n        System.out.println(\" (Ctrl+C para detener)\");\n        System.out.println(\"==============================================\");\n    }\n\n    private static void cargarDatosDemo(ServicioReservas s) {\n        s.crear(new Reserva(\"LAB-1\", \"Prof. Flores\", \"2026-10-22\", \"07:00\", \"08:35\"));\n        s.crear(new Reserva(\"LAB-2\", \"Grupo PROG V\", \"2026-10-22\", \"09:00\", \"10:30\"));\n        s.crear(new Reserva(\"LAB-1\", \"Club de Robótica\", \"2026-10-23\", \"14:00\", \"16:00\"));\n    }\n}\n"},{"nombre":"ReservasHandler.java","ruta":"ReservasLabAPI/src/reservas/servidor/ReservasHandler.java","lenguaje":"java","lineas":137,"texto":"package reservas.servidor;\n\nimport java.io.ByteArrayOutputStream;\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStream;\nimport java.nio.charset.StandardCharsets;\nimport java.time.LocalTime;\n\nimport com.sun.net.httpserver.HttpExchange;\nimport com.sun.net.httpserver.HttpHandler;\n\nimport reservas.modelo.Reserva;\nimport reservas.negocio.ServicioReservas;\nimport reservas.negocio.ValidacionException;\n\n/**\n * Atiende todas las rutas /api/reservas.\n *\n *   GET    /api/reservas        -> RF-01 listar\n *   GET    /api/reservas/{id}   -> RF-02 consultar\n *   POST   /api/reservas        -> RF-03 crear\n *   PUT    /api/reservas/{id}   -> RF-04 actualizar\n *   DELETE /api/reservas/{id}   -> RF-05 cancelar\n *\n * Aquí se hacen visibles varios requisitos NO funcionales:\n *   RNF-01 Seguridad   : encabezado X-API-KEY obligatorio en operaciones de escritura.\n *   RNF-02 Rendimiento : se mide y registra el tiempo de cada solicitud (ms).\n *   RNF-03 Interoperab.: todas las respuestas en JSON UTF-8 con códigos HTTP estándar.\n */\npublic class ReservasHandler implements HttpHandler {\n\n    private static final String API_KEY = \"unachi-prog5\";\n    private static final String BASE = \"/api/reservas\";\n\n    private final ServicioReservas servicio;\n\n    public ReservasHandler(ServicioReservas servicio) {\n        this.servicio = servicio;\n    }\n\n    @Override\n    public void handle(HttpExchange ex) throws IOException {\n        long inicio = System.nanoTime();\n        String metodo = ex.getRequestMethod();\n        String ruta = ex.getRequestURI().getPath();\n        int codigo;\n        String cuerpo;\n\n        try {\n            Integer id = extraerId(ruta);\n\n            // RNF-01: solo lectura es pública; escribir requiere API key\n            if (!\"GET\".equals(metodo) && !API_KEY.equals(ex.getRequestHeaders().getFirst(\"X-API-KEY\"))) {\n                throw new ValidacionException(401, \"Falta o es inválido el encabezado X-API-KEY\");\n            }\n\n            if (\"GET\".equals(metodo) && id == null) {\n                codigo = 200;\n                cuerpo = Json.deLista(servicio.listar());\n            } else if (\"GET\".equals(metodo)) {\n                codigo = 200;\n                cuerpo = Json.deReserva(servicio.obtener(id));\n            } else if (\"POST\".equals(metodo) && id == null) {\n                Reserva r = servicio.crear(Json.aReserva(leerCuerpo(ex)));\n                codigo = 201;\n                cuerpo = Json.deReserva(r);\n            } else if (\"PUT\".equals(metodo) && id != null) {\n                Reserva r = servicio.actualizar(id, Json.aReserva(leerCuerpo(ex)));\n                codigo = 200;\n                cuerpo = Json.deReserva(r);\n            } else if (\"DELETE\".equals(metodo) && id != null) {\n                servicio.cancelar(id);\n                codigo = 204;\n                cuerpo = \"\";\n            } else {\n                throw new ValidacionException(405, \"Método \" + metodo + \" no permitido en \" + ruta);\n            }\n        } catch (ValidacionException e) {\n            codigo = e.getCodigoHttp();\n            cuerpo = Json.error(codigo, e.getMessage());\n        } catch (IllegalArgumentException e) {\n            codigo = 400;\n            cuerpo = Json.error(400, \"Solicitud mal formada: \" + e.getMessage());\n        } catch (Exception e) {\n            codigo = 500;\n            cuerpo = Json.error(500, \"Error interno del servidor\");\n            e.printStackTrace();\n        }\n\n        responder(ex, codigo, cuerpo);\n\n        // RNF-02: bitácora con tiempo de respuesta\n        long ms = (System.nanoTime() - inicio) / 1_000_000;\n        System.out.printf(\"[%s] %-6s %-22s -> %d (%d ms) [%s]%n\",\n                LocalTime.now().withNano(0), metodo, ruta, codigo, ms, Thread.currentThread().getName());\n    }\n\n    /** Devuelve el {id} de /api/reservas/{id}, o null si la ruta es /api/reservas. */\n    private Integer extraerId(String ruta) {\n        String resto = ruta.substring(BASE.length());\n        if (resto.isEmpty() || \"/\".equals(resto)) {\n            return null;\n        }\n        try {\n            return Integer.parseInt(resto.substring(1));\n        } catch (NumberFormatException e) {\n            throw new ValidacionException(400, \"El id debe ser numérico\");\n        }\n    }\n\n    private String leerCuerpo(HttpExchange ex) throws IOException {\n        InputStream in = ex.getRequestBody();\n        ByteArrayOutputStream buf = new ByteArrayOutputStream();\n        byte[] b = new byte[1024];\n        int n;\n        while ((n = in.read(b)) != -1) {\n            buf.write(b, 0, n);\n        }\n        return new String(buf.toByteArray(), StandardCharsets.UTF_8);\n    }\n\n    private void responder(HttpExchange ex, int codigo, String cuerpo) throws IOException {\n        byte[] bytes = cuerpo.getBytes(StandardCharsets.UTF_8);\n        ex.getResponseHeaders().set(\"Content-Type\", \"application/json; charset=UTF-8\");\n        if (codigo == 204) {\n            ex.sendResponseHeaders(204, -1);\n        } else {\n            ex.sendResponseHeaders(codigo, bytes.length);\n            OutputStream os = ex.getResponseBody();\n            os.write(bytes);\n            os.close();\n        }\n        ex.close();\n    }\n}\n"},{"nombre":"ServicioReservas.java","ruta":"ReservasLabAPI/src/reservas/negocio/ServicioReservas.java","lenguaje":"java","lineas":108,"texto":"package reservas.negocio;\n\nimport java.util.Arrays;\nimport java.util.List;\n\nimport reservas.datos.RepositorioReservas;\nimport reservas.modelo.Reserva;\n\n/**\n * Capa de negocio: aquí viven las REGLAS que salen de los requisitos funcionales.\n * Ni el servidor HTTP ni el cliente conocen estas reglas; solo las consumen.\n */\npublic class ServicioReservas {\n\n    // RF-06: solo existen estos laboratorios en la Escuela\n    private static final List<String> LABORATORIOS = Arrays.asList(\"LAB-1\", \"LAB-2\", \"LAB-3\");\n\n    private final RepositorioReservas repo;\n\n    public ServicioReservas(RepositorioReservas repo) {\n        this.repo = repo;\n    }\n\n    /** RF-01: listar reservas. */\n    public List<Reserva> listar() {\n        return repo.listarTodas();\n    }\n\n    /** RF-02: consultar una reserva por su identificador. */\n    public Reserva obtener(int id) {\n        Reserva r = repo.buscarPorId(id);\n        if (r == null) {\n            throw new ValidacionException(404, \"No existe la reserva con id \" + id);\n        }\n        return r;\n    }\n\n    /** RF-03: registrar una reserva validando datos y choques de horario. */\n    public Reserva crear(Reserva r) {\n        validarDatos(r);\n        validarChoque(r, 0);\n        r.setEstado(\"ACTIVA\");\n        return repo.guardar(r);\n    }\n\n    /** RF-04: modificar una reserva existente. */\n    public Reserva actualizar(int id, Reserva cambios) {\n        Reserva actual = obtener(id);\n        validarDatos(cambios);\n        validarChoque(cambios, id);\n        actual.setLaboratorio(cambios.getLaboratorio());\n        actual.setSolicitante(cambios.getSolicitante());\n        actual.setFecha(cambios.getFecha());\n        actual.setHoraInicio(cambios.getHoraInicio());\n        actual.setHoraFin(cambios.getHoraFin());\n        return repo.guardar(actual);\n    }\n\n    /** RF-05: cancelar (eliminar) una reserva. */\n    public void cancelar(int id) {\n        if (!repo.eliminar(id)) {\n            throw new ValidacionException(404, \"No existe la reserva con id \" + id);\n        }\n    }\n\n    // ---------------- reglas privadas ----------------\n\n    private void validarDatos(Reserva r) {\n        if (vacio(r.getLaboratorio()) || vacio(r.getSolicitante()) || vacio(r.getFecha())\n                || vacio(r.getHoraInicio()) || vacio(r.getHoraFin())) {\n            throw new ValidacionException(400,\n                    \"Campos obligatorios: laboratorio, solicitante, fecha, horaInicio, horaFin\");\n        }\n        if (!LABORATORIOS.contains(r.getLaboratorio().toUpperCase())) {\n            throw new ValidacionException(400, \"Laboratorio inválido. Use: \" + LABORATORIOS);\n        }\n        r.setLaboratorio(r.getLaboratorio().toUpperCase());\n        if (!r.getFecha().matches(\"\\\\d{4}-\\\\d{2}-\\\\d{2}\")) {\n            throw new ValidacionException(400, \"La fecha debe tener formato yyyy-MM-dd\");\n        }\n        if (!r.getHoraInicio().matches(\"\\\\d{2}:\\\\d{2}\") || !r.getHoraFin().matches(\"\\\\d{2}:\\\\d{2}\")) {\n            throw new ValidacionException(400, \"Las horas deben tener formato HH:mm\");\n        }\n        if (r.getHoraInicio().compareTo(r.getHoraFin()) >= 0) {\n            throw new ValidacionException(400, \"horaInicio debe ser menor que horaFin\");\n        }\n    }\n\n    /** RF-07: un laboratorio no puede tener dos reservas que se solapen. */\n    private void validarChoque(Reserva nueva, int idIgnorado) {\n        for (Reserva r : repo.listarPorLaboratorioYFecha(nueva.getLaboratorio(), nueva.getFecha())) {\n            if (r.getId() == idIgnorado) {\n                continue;\n            }\n            boolean seSolapan = nueva.getHoraInicio().compareTo(r.getHoraFin()) < 0\n                    && r.getHoraInicio().compareTo(nueva.getHoraFin()) < 0;\n            if (seSolapan) {\n                throw new ValidacionException(409, \"Choque de horario con la reserva #\" + r.getId()\n                        + \" (\" + r.getHoraInicio() + \"-\" + r.getHoraFin() + \")\");\n            }\n        }\n    }\n\n    private boolean vacio(String s) {\n        return s == null || s.trim().isEmpty();\n    }\n}\n"},{"nombre":"RepositorioReservas.java","ruta":"ReservasLabAPI/src/reservas/datos/RepositorioReservas.java","lenguaje":"java","lineas":56,"texto":"package reservas.datos;\n\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.concurrent.ConcurrentHashMap;\nimport java.util.concurrent.atomic.AtomicInteger;\n\nimport reservas.modelo.Reserva;\n\n/**\n * Capa de acceso a datos (en memoria para el ejemplo).\n *\n * RNF-04 (Concurrencia): el servidor atiende varias solicitudes a la vez,\n * por eso se usa ConcurrentHashMap y AtomicInteger en lugar de HashMap e int.\n * En el proyecto real esta clase se reemplaza por JDBC + MySQL/PostgreSQL\n * sin tocar las demás capas.\n */\npublic class RepositorioReservas {\n\n    private final Map<Integer, Reserva> tabla = new ConcurrentHashMap<Integer, Reserva>();\n    private final AtomicInteger secuencia = new AtomicInteger(0);\n\n    public Reserva guardar(Reserva r) {\n        if (r.getId() == 0) {\n            r.setId(secuencia.incrementAndGet());\n        }\n        tabla.put(r.getId(), r);\n        return r;\n    }\n\n    public Reserva buscarPorId(int id) {\n        return tabla.get(id);\n    }\n\n    public List<Reserva> listarTodas() {\n        List<Reserva> lista = new ArrayList<Reserva>(tabla.values());\n        lista.sort((a, b) -> Integer.compare(a.getId(), b.getId()));\n        return lista;\n    }\n\n    public List<Reserva> listarPorLaboratorioYFecha(String lab, String fecha) {\n        List<Reserva> res = new ArrayList<Reserva>();\n        for (Reserva r : tabla.values()) {\n            if (r.getLaboratorio().equalsIgnoreCase(lab) && r.getFecha().equals(fecha)) {\n                res.add(r);\n            }\n        }\n        return res;\n    }\n\n    public boolean eliminar(int id) {\n        return tabla.remove(id) != null;\n    }\n}\n"},{"nombre":"Reserva.java","ruta":"ReservasLabAPI/src/reservas/modelo/Reserva.java","lenguaje":"java","lineas":58,"texto":"package reservas.modelo;\n\n/**\n * Entidad del dominio: una reserva de laboratorio.\n * RF-01..RF-05 trabajan sobre esta clase.\n */\npublic class Reserva {\n\n    private int id;\n    private String laboratorio;   // ej. \"LAB-1\"\n    private String solicitante;   // nombre del docente o estudiante\n    private String fecha;         // formato yyyy-MM-dd\n    private String horaInicio;    // formato HH:mm\n    private String horaFin;       // formato HH:mm\n    private String estado;        // ACTIVA | CANCELADA\n\n    public Reserva() {\n        this.estado = \"ACTIVA\";\n    }\n\n    public Reserva(String laboratorio, String solicitante, String fecha,\n                   String horaInicio, String horaFin) {\n        this();\n        this.laboratorio = laboratorio;\n        this.solicitante = solicitante;\n        this.fecha = fecha;\n        this.horaInicio = horaInicio;\n        this.horaFin = horaFin;\n    }\n\n    public int getId() { return id; }\n    public void setId(int id) { this.id = id; }\n\n    public String getLaboratorio() { return laboratorio; }\n    public void setLaboratorio(String laboratorio) { this.laboratorio = laboratorio; }\n\n    public String getSolicitante() { return solicitante; }\n    public void setSolicitante(String solicitante) { this.solicitante = solicitante; }\n\n    public String getFecha() { return fecha; }\n    public void setFecha(String fecha) { this.fecha = fecha; }\n\n    public String getHoraInicio() { return horaInicio; }\n    public void setHoraInicio(String horaInicio) { this.horaInicio = horaInicio; }\n\n    public String getHoraFin() { return horaFin; }\n    public void setHoraFin(String horaFin) { this.horaFin = horaFin; }\n\n    public String getEstado() { return estado; }\n    public void setEstado(String estado) { this.estado = estado; }\n\n    @Override\n    public String toString() {\n        return String.format(\"#%d %s | %s | %s %s-%s | %s\",\n                id, laboratorio, solicitante, fecha, horaInicio, horaFin, estado);\n    }\n}\n"},{"nombre":"ClienteConsola.java","ruta":"ReservasLabAPI/src/reservas/cliente/ClienteConsola.java","lenguaje":"java","lineas":255,"texto":"package reservas.cliente;\n\nimport java.io.ByteArrayOutputStream;\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.io.OutputStream;\nimport java.net.ConnectException;\nimport java.net.HttpURLConnection;\nimport java.net.SocketTimeoutException;\nimport java.net.URL;\nimport java.nio.charset.StandardCharsets;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.Scanner;\nimport java.util.concurrent.ExecutorService;\nimport java.util.concurrent.Executors;\nimport java.util.concurrent.Future;\n\n/**\n * CLIENTE de la arquitectura cliente-servidor (aplicación de consola).\n * Solo conoce el CONTRATO de la API (rutas, métodos y JSON); no conoce\n * las clases internas del servidor.\n *\n * Ejecutar:  java -cp build reservas.cliente.ClienteConsola\n *            java -cp build reservas.cliente.ClienteConsola demo   (sin menú)\n */\npublic class ClienteConsola {\n\n    private static final String URL_BASE = \"http://localhost:8080/api/reservas\";\n    private static final String API_KEY = \"unachi-prog5\";\n\n    // RNF-05 (Disponibilidad percibida): el cliente no se queda colgado\n    private static final int TIMEOUT_CONEXION_MS = 3000;\n    private static final int TIMEOUT_LECTURA_MS = 5000;\n\n    public static void main(String[] args) throws Exception {\n        if (args.length > 0 && \"demo\".equals(args[0])) {\n            demoAutomatica();\n            return;\n        }\n        Scanner sc = new Scanner(System.in, \"UTF-8\");\n        int op;\n        do {\n            System.out.println();\n            System.out.println(\"===== CLIENTE RESERVAS DE LABORATORIO =====\");\n            System.out.println(\"1. Listar reservas            (GET)\");\n            System.out.println(\"2. Consultar reserva por id   (GET)\");\n            System.out.println(\"3. Crear reserva              (POST)\");\n            System.out.println(\"4. Modificar reserva          (PUT)\");\n            System.out.println(\"5. Cancelar reserva           (DELETE)\");\n            System.out.println(\"6. Prueba de carga RNF (20 solicitudes simultáneas)\");\n            System.out.println(\"0. Salir\");\n            System.out.print(\"Opción: \");\n            op = leerEntero(sc);\n            switch (op) {\n                case 1: mostrar(enviar(\"GET\", URL_BASE, null)); break;\n                case 2:\n                    System.out.print(\"Id: \");\n                    mostrar(enviar(\"GET\", URL_BASE + \"/\" + leerEntero(sc), null));\n                    break;\n                case 3: mostrar(enviar(\"POST\", URL_BASE, pedirDatos(sc))); break;\n                case 4:\n                    System.out.print(\"Id a modificar: \");\n                    int id = leerEntero(sc);\n                    mostrar(enviar(\"PUT\", URL_BASE + \"/\" + id, pedirDatos(sc)));\n                    break;\n                case 5:\n                    System.out.print(\"Id a cancelar: \");\n                    mostrar(enviar(\"DELETE\", URL_BASE + \"/\" + leerEntero(sc), null));\n                    break;\n                case 6: pruebaDeCarga(20); break;\n                case 0: System.out.println(\"Hasta luego.\"); break;\n                default: System.out.println(\"Opción inválida.\");\n            }\n        } while (op != 0);\n    }\n\n    // ------------------------------------------------------------------\n    //  Comunicación HTTP\n    // ------------------------------------------------------------------\n\n    /** Resultado simple de una llamada HTTP. */\n    static class Respuesta {\n        final int codigo;\n        final String cuerpo;\n        final long ms;\n        Respuesta(int codigo, String cuerpo, long ms) {\n            this.codigo = codigo;\n            this.cuerpo = cuerpo;\n            this.ms = ms;\n        }\n    }\n\n    static Respuesta enviar(String metodo, String url, String json) {\n        long t0 = System.currentTimeMillis();\n        HttpURLConnection con = null;\n        try {\n            con = (HttpURLConnection) new URL(url).openConnection();\n            con.setRequestMethod(metodo);\n            con.setConnectTimeout(TIMEOUT_CONEXION_MS);\n            con.setReadTimeout(TIMEOUT_LECTURA_MS);\n            con.setRequestProperty(\"Accept\", \"application/json\");\n            con.setRequestProperty(\"X-API-KEY\", API_KEY);\n            if (json != null) {\n                con.setDoOutput(true);\n                con.setRequestProperty(\"Content-Type\", \"application/json; charset=UTF-8\");\n                OutputStream os = con.getOutputStream();\n                os.write(json.getBytes(StandardCharsets.UTF_8));\n                os.close();\n            }\n            int codigo = con.getResponseCode();\n            InputStream in = codigo >= 400 ? con.getErrorStream() : con.getInputStream();\n            String cuerpo = in == null ? \"\" : leerTodo(in);\n            return new Respuesta(codigo, cuerpo, System.currentTimeMillis() - t0);\n        } catch (ConnectException e) {\n            return new Respuesta(-1, \"No se pudo conectar: ¿el servidor está encendido?\",\n                    System.currentTimeMillis() - t0);\n        } catch (SocketTimeoutException e) {\n            return new Respuesta(-1, \"Tiempo de espera agotado (timeout)\",\n                    System.currentTimeMillis() - t0);\n        } catch (IOException e) {\n            return new Respuesta(-1, \"Error de red: \" + e.getMessage(),\n                    System.currentTimeMillis() - t0);\n        } finally {\n            if (con != null) con.disconnect();\n        }\n    }\n\n    // ------------------------------------------------------------------\n    //  RNF: prueba de rendimiento / concurrencia\n    // ------------------------------------------------------------------\n\n    static void pruebaDeCarga(int n) throws Exception {\n        System.out.println(\"Enviando \" + n + \" solicitudes GET en paralelo...\");\n        ExecutorService pool = Executors.newFixedThreadPool(n);\n        List<Future<Respuesta>> futuros = new ArrayList<Future<Respuesta>>();\n        long t0 = System.currentTimeMillis();\n        for (int i = 0; i < n; i++) {\n            futuros.add(pool.submit(() -> enviar(\"GET\", URL_BASE, null)));\n        }\n        long max = 0, suma = 0;\n        int ok = 0;\n        for (Future<Respuesta> f : futuros) {\n            Respuesta r = f.get();\n            if (r.codigo == 200) ok++;\n            suma += r.ms;\n            max = Math.max(max, r.ms);\n        }\n        pool.shutdown();\n        long total = System.currentTimeMillis() - t0;\n        System.out.printf(\"Exitosas: %d/%d | promedio: %d ms | máximo: %d ms | total: %d ms%n\",\n                ok, n, suma / n, max, total);\n        System.out.println(max <= 500\n                ? \"CUMPLE RNF-02 (tiempo de respuesta <= 500 ms)\"\n                : \"NO CUMPLE RNF-02 (tiempo de respuesta <= 500 ms)\");\n    }\n\n    // ------------------------------------------------------------------\n    //  Demo automática (útil para proyectar en clase)\n    // ------------------------------------------------------------------\n\n    static void demoAutomatica() throws Exception {\n        paso(\"1) Listar reservas iniciales\");\n        mostrar(enviar(\"GET\", URL_BASE, null));\n\n        paso(\"2) Crear reserva válida (201 Created)\");\n        mostrar(enviar(\"POST\", URL_BASE, json(\"LAB-3\", \"Ana Pérez\", \"2026-10-24\", \"08:00\", \"10:00\")));\n\n        paso(\"3) Crear reserva que choca con #1 (409 Conflict)\");\n        mostrar(enviar(\"POST\", URL_BASE, json(\"LAB-1\", \"Luis Gómez\", \"2026-10-22\", \"08:00\", \"09:00\")));\n\n        paso(\"4) Crear reserva con datos incompletos (400 Bad Request)\");\n        mostrar(enviar(\"POST\", URL_BASE, \"{\\\"laboratorio\\\":\\\"LAB-2\\\"}\"));\n\n        paso(\"5) Consultar reserva inexistente (404 Not Found)\");\n        mostrar(enviar(\"GET\", URL_BASE + \"/99\", null));\n\n        paso(\"6) Modificar reserva #2 (200 OK)\");\n        mostrar(enviar(\"PUT\", URL_BASE + \"/2\", json(\"LAB-2\", \"Grupo PROG V\", \"2026-10-22\", \"10:30\", \"12:00\")));\n\n        paso(\"7) Cancelar reserva #3 (204 No Content)\");\n        mostrar(enviar(\"DELETE\", URL_BASE + \"/3\", null));\n\n        paso(\"8) Escribir sin API key (401 Unauthorized) - RNF-01 Seguridad\");\n        mostrar(enviarSinClave());\n\n        paso(\"9) Prueba de carga - RNF-02 Rendimiento / RNF-04 Concurrencia\");\n        pruebaDeCarga(20);\n    }\n\n    private static Respuesta enviarSinClave() throws IOException {\n        HttpURLConnection con = (HttpURLConnection) new URL(URL_BASE + \"/1\").openConnection();\n        con.setRequestMethod(\"DELETE\");\n        con.setConnectTimeout(TIMEOUT_CONEXION_MS);\n        con.setReadTimeout(TIMEOUT_LECTURA_MS);\n        int codigo = con.getResponseCode();\n        InputStream in = con.getErrorStream();\n        return new Respuesta(codigo, in == null ? \"\" : leerTodo(in), 0);\n    }\n\n    // ------------------------------------------------------------------\n    //  Utilidades\n    // ------------------------------------------------------------------\n\n    private static String pedirDatos(Scanner sc) {\n        System.out.print(\"Laboratorio (LAB-1/LAB-2/LAB-3): \");\n        String lab = sc.nextLine().trim();\n        System.out.print(\"Solicitante: \");\n        String sol = sc.nextLine().trim();\n        System.out.print(\"Fecha (yyyy-MM-dd): \");\n        String fecha = sc.nextLine().trim();\n        System.out.print(\"Hora inicio (HH:mm): \");\n        String hi = sc.nextLine().trim();\n        System.out.print(\"Hora fin (HH:mm): \");\n        String hf = sc.nextLine().trim();\n        return json(lab, sol, fecha, hi, hf);\n    }\n\n    private static String json(String lab, String sol, String fecha, String hi, String hf) {\n        return \"{\\\"laboratorio\\\":\\\"\" + lab + \"\\\",\\\"solicitante\\\":\\\"\" + sol\n                + \"\\\",\\\"fecha\\\":\\\"\" + fecha + \"\\\",\\\"horaInicio\\\":\\\"\" + hi\n                + \"\\\",\\\"horaFin\\\":\\\"\" + hf + \"\\\"}\";\n    }\n\n    private static void mostrar(Respuesta r) {\n        String estado = r.codigo == -1 ? \"SIN CONEXIÓN\" : \"HTTP \" + r.codigo;\n        System.out.println(\"  <- \" + estado + \" (\" + r.ms + \" ms)\");\n        if (!r.cuerpo.isEmpty()) {\n            System.out.println(\"  \" + r.cuerpo.replace(\"},{\", \"},\\n   {\"));\n        }\n    }\n\n    private static void paso(String t) {\n        System.out.println();\n        System.out.println(\">>> \" + t);\n    }\n\n    private static int leerEntero(Scanner sc) {\n        try {\n            return Integer.parseInt(sc.nextLine().trim());\n        } catch (NumberFormatException e) {\n            return -99;\n        }\n    }\n\n    private static String leerTodo(InputStream in) throws IOException {\n        ByteArrayOutputStream buf = new ByteArrayOutputStream();\n        byte[] b = new byte[1024];\n        int n;\n        while ((n = in.read(b)) != -1) buf.write(b, 0, n);\n        in.close();\n        return new String(buf.toByteArray(), StandardCharsets.UTF_8);\n    }\n}\n"},{"nombre":"CONTRATO_API.md","ruta":"ReservasLabAPI/CONTRATO_API.md","lenguaje":"markdown","lineas":59,"texto":"# Contrato de la API — Reservas de Laboratorios (v1)\n\n**URL base:** `http://localhost:8080/api/reservas`\n**Formato:** JSON (UTF-8) en solicitudes y respuestas\n**Autenticación:** encabezado `X-API-KEY: unachi-prog5` en POST, PUT y DELETE (RNF-01)\n\n## Recurso `Reserva`\n\n| Campo        | Tipo    | Obligatorio | Regla                                   |\n|--------------|---------|-------------|-----------------------------------------|\n| id           | entero  | lo asigna el servidor | autoincremental              |\n| laboratorio  | texto   | sí          | `LAB-1`, `LAB-2` o `LAB-3` (RF-06)       |\n| solicitante  | texto   | sí          | no vacío                                 |\n| fecha        | texto   | sí          | `yyyy-MM-dd`                             |\n| horaInicio   | texto   | sí          | `HH:mm`, menor que horaFin               |\n| horaFin      | texto   | sí          | `HH:mm`                                  |\n| estado       | texto   | lo asigna el servidor | `ACTIVA`                       |\n\n## Endpoints\n\n| RF    | Método | Ruta                  | Cuerpo   | Éxito             | Errores posibles   |\n|-------|--------|-----------------------|----------|-------------------|--------------------|\n| RF-01 | GET    | `/api/reservas`       | —        | 200 + lista       | 500                |\n| RF-02 | GET    | `/api/reservas/{id}`  | —        | 200 + reserva     | 400, 404           |\n| RF-03 | POST   | `/api/reservas`       | Reserva  | 201 + reserva     | 400, 401, 409      |\n| RF-04 | PUT    | `/api/reservas/{id}`  | Reserva  | 200 + reserva     | 400, 401, 404, 409 |\n| RF-05 | DELETE | `/api/reservas/{id}`  | —        | 204 (sin cuerpo)  | 401, 404           |\n\n## Ejemplo — crear reserva\n\nSolicitud:\n```http\nPOST /api/reservas HTTP/1.1\nContent-Type: application/json\nX-API-KEY: unachi-prog5\n\n{\"laboratorio\":\"LAB-3\",\"solicitante\":\"Ana Pérez\",\"fecha\":\"2026-10-24\",\"horaInicio\":\"08:00\",\"horaFin\":\"10:00\"}\n```\n\nRespuesta `201 Created`:\n```json\n{\"id\":4,\"laboratorio\":\"LAB-3\",\"solicitante\":\"Ana Pérez\",\"fecha\":\"2026-10-24\",\"horaInicio\":\"08:00\",\"horaFin\":\"10:00\",\"estado\":\"ACTIVA\"}\n```\n\n## Formato de error (igual para todos los endpoints)\n\n```json\n{\"error\":409,\"mensaje\":\"Choque de horario con la reserva #1 (07:00-08:35)\"}\n```\n\n| Código | Significado en esta API                              |\n|--------|------------------------------------------------------|\n| 400    | Datos incompletos o con formato inválido             |\n| 401    | Falta o es incorrecta la `X-API-KEY`                 |\n| 404    | La reserva no existe                                 |\n| 405    | Método no permitido para esa ruta                    |\n| 409    | Choque de horario en el mismo laboratorio (RF-07)    |\n| 500    | Error interno del servidor                           |\n"}]};
